function saveJSON(file, data) {
  fs.writeFileSync(file, JSON.stringify(data, null, 2));
  if (!suppressClusterBroadcast && CLUSTER_SYNC_FILES.has(file)) {
    broadcastStateReload(`save:${path.basename(file)}`).catch(() => {});
  }
}
