        now: { title: current.title, description: '', start: current.start, stop: next.start },
        next: slots[i + 1] ? { title: slots[i + 1].title, description: '', start: slots[i + 1].start, stop: (slots[i + 2]?.start || (slots[i + 1].start + 60 * 60 * 1000)) } : null
