function readLinuxInterfaceBytes() {
  try {
    const raw = fs.readFileSync('/proc/net/dev', 'utf8');
    let rxBytes = 0;
    let txBytes = 0;
    for (const line of raw.split('\n').slice(2)) {
      const trimmed = String(line || '').trim();
      if (!trimmed) continue;
      const colonIdx = trimmed.indexOf(':');
      if (colonIdx < 0) continue;
      const stats = trimmed.slice(colonIdx + 1).trim().split(/\s+/);
      if (stats.length < 9) continue;
      const rx = parseInt(stats[0], 10);
      const tx = parseInt(stats[8], 10);
      if (Number.isFinite(rx)) rxBytes += rx;
      if (Number.isFinite(tx)) txBytes += tx;
    }
    return { rxBytes, txBytes };
  } catch {
    return null;
  }
}
function sampleInterfaceNetworkRates(now = Date.now()) {
  const snap = readLinuxInterfaceBytes();
  if (!snap) return { ingressMbps: 0, egressMbps: 0 };
  const prev = lastInterfaceNetSample;
  lastInterfaceNetSample = { ts: now, rxBytes: snap.rxBytes, txBytes: snap.txBytes };
  if (!prev.ts || prev.ts >= now) return { ingressMbps: 0, egressMbps: 0 };
  const elapsedSec = Math.max(1, (now - prev.ts) / 1000);
  const rxDelta = Math.max(0, snap.rxBytes - Number(prev.rxBytes || 0));
  const txDelta = Math.max(0, snap.txBytes - Number(prev.txBytes || 0));
  const ingressMbps = Math.round(((rxDelta * 8) / (elapsedSec * 1000 * 1000)) * 10) / 10;
  const egressMbps = Math.round(((txDelta * 8) / (elapsedSec * 1000 * 1000)) * 10) / 10;
  return { ingressMbps, egressMbps };
}
