  for (const category of Object.keys(out)) {
    const input = Array.isArray(raw[category]) ? raw[category] : [];
    const seenSlug = new Set();
    let index = 0;
    for (const entry of input) {
      if (!entry || typeof entry !== 'object') continue;
      const name = String(entry.name || '').trim();
      const url = normalizeUrlExact(entry.url || '');
      if (!name || !url) continue;
      let slug = createSlug(String(entry.slug || ''));
      if (!slug) slug = `custom_${category}_${md5(url || name)}`;
      let uniqueSlugValue = slug;
      let i = 1;
      while (seenSlug.has(uniqueSlugValue)) uniqueSlugValue = `${slug}-${i++}`;
      seenSlug.add(uniqueSlugValue);
      const id = createSlug(String(entry.id || '')) || `c${md5(`${category}|${uniqueSlugValue}|${url}`)}`;
      const logoRaw = String(entry.logo || '').trim();
      const logo = normalizeUrl(logoRaw) || logoRaw;
      const orderRaw = parseInt(entry.order, 10);
      const order = Number.isFinite(orderRaw) ? orderRaw : (index + 1);
      const backupUrls = normalizeBackupUrls(entry.backup_urls || entry.backupUrls || entry.urls || []);
      const youtubeUrl = normalizeUrlExact(entry.youtube_url || entry.youtubeUrl || '');
      const embedUrl = normalizeUrlExact(entry.embed_url || entry.embedUrl || '');
      const upstream = parseCustomChannelUpstreamInput(entry);
      out[category].push({
        id,
        slug: uniqueSlugValue,
        name,
        url,
        logo,
        order,
        backup_urls: backupUrls,
        youtube_url: youtubeUrl,
        embed_url: embedUrl,
        user_agent: upstream.user_agent,
        upstream_headers: upstream.upstream_headers
      });
      index += 1;
    }
    out[category].sort((a, b) => Number(a.order || 0) - Number(b.order || 0));
    out[category].forEach((item, idx) => { item.order = idx + 1; });
  }
