  if (!cleanName || !cleanUrl) return null;
  if (!customChannels[safeCategory]) customChannels[safeCategory] = [];
  const requestedSlug = createSlug(String(options.slug || ''));
  const baseSlug = requestedSlug || `custom_${safeCategory}_${md5(cleanUrl || cleanName)}`;
  const duplicate = customChannels[safeCategory].some(ch => {
    const currentUrl = normalizeUrlExact(ch.url || '');
    if (currentUrl === cleanUrl) return true;
    if (requestedSlug && createSlug(ch.slug || '') === requestedSlug) return true;
    return false;
  });
  if (duplicate) return null;
  let slug = baseSlug;
