  const need = Math.max(1, parseInt(settings.referral_points_needed_for_premium, 10) || DEFAULT_FIREBASE_AUTH_CONFIG.referral_points_needed_for_premium);
  const days = Math.max(1, parseInt(settings.referral_points_premium_days, 10) || DEFAULT_FIREBASE_AUTH_CONFIG.referral_points_premium_days);
  let balance = Math.max(0, parseInt(profile.referral_points, 10) || 0);
