function syncKoolChannelsFromService(options = {}) {
  const persist = options.persist !== false;
  const replaceAll = options.replaceAll === true;
  const refreshCategory = String(options.refreshCategory || '').trim();
  const fetched = koolService.getAllChannels();
  if (!Array.isArray(fetched) || !fetched.length) return koolChannelsDb;
  const rawItems = [];
  for (const channel of fetched) {
    const name = String(channel?.name || '').trim();
    const url = normalizeUrl(channel?.url || '');
    const koolCategory = String(channel?.category || '').trim();
    if (!name || !url || !koolCategory) continue;
    rawItems.push({
      name,
      url,
      koolCategory,
      koolId: resolveStableKoolChannelId(url, koolCategory, name, channel?.id || channel?.koolId),
      logo: String(channel?.logo || ''),
      description: String(channel?.description || '')
    });
  }
  const mergedItems = mergeChannelVariantList(rawItems, { mergeByCategory: true, maxBackups: 16 });
  const freshMap = {};
  for (const channel of mergedItems) {
    const name = String(channel?.name || '').trim();
    const url = normalizeUrl(channel?.url || '');
    const koolCategory = String(channel?.koolCategory || '').trim();
    if (!name || !url || !koolCategory) continue;
    const koolId = resolveStableKoolChannelId(url, koolCategory, name, channel?.koolId || channel?.id);
    const slug = buildKoolChannelSlug('kool', koolCategory, koolId);
    freshMap[slug] = {
      name,
      url,
      type: 'kool',
      source: 'kool',
      sourceKey: 'kool',
      slug,
      id: md5(slug),
      visible: appConfig.visible_channels[slug] !== false,
      koolCategory,
      koolId,
      logo: String(channel?.logo || ''),
      description: String(channel?.description || ''),
      backup_urls: normalizeBackupUrls(channel?.backup_urls || [], { maxItems: 16 })
    };
  }
  if (!Object.keys(freshMap).length) return koolChannelsDb;
  let next = replaceAll ? {} : { ...koolChannelsDb };
  if (refreshCategory && !replaceAll) {
    for (const [slug, ch] of Object.entries(next)) {
      if (String(ch?.koolCategory || '').trim() === refreshCategory) delete next[slug];
    }
  }
  const { merged, slugRemap } = mergeKoolChannelDbWithRemap(next, freshMap);
  next = merged;
  koolChannelsDb = normalizeKoolChannelsDb(next);
  if (slugRemap.size) {
    const remapChanged = applyChannelSlugRemap(slugRemap, { ...allChannelsDb, ...sportsDb, ...nimiChannelsDb, ...koolChannelsDb, ...koolLokkeChannelsDb });
    if (remapChanged) {
      saveJSON(CATEGORIES_FILE, customCategories);
      saveJSON(PLAYLISTS_FILE, customPlaylists);
      saveJSON(CONFIG_FILE, appConfig);
    }
  }
  if (persist) saveJSON(KOOL_CACHE_FILE, koolChannelsDb);
  return koolChannelsDb;
}
