function getKoolCategorySummaries() {
  const map = new Map();
  for (const channel of Object.values(koolChannelsDb)) {
    if (!channel || channel.type !== 'kool') continue;
    const category = String(channel.koolCategory || '').trim();
    if (!category) continue;
    if (!map.has(category)) map.set(category, { name: category, slug: koolCategorySlug(category), count: 0 });
    map.get(category).count += 1;
  }
  const summaries = Array.from(map.values()).sort((a, b) => a.name.localeCompare(b.name));
  let changed = false;
  for (const item of summaries) {
    if (appConfig.kool_main_categories[item.slug] === undefined) {
      appConfig.kool_main_categories[item.slug] = true;
      changed = true;
    }
  }
  for (const slug of Object.keys(appConfig.kool_main_categories || {})) {
    if (!summaries.some(item => item.slug === slug)) {
      delete appConfig.kool_main_categories[slug];
      changed = true;
    }
  }
  if (changed) saveJSON(CONFIG_FILE, appConfig);
  return summaries.map(item => ({ ...item, visibleOnMain: isKoolCategoryVisible(item.slug) }));
}
