function pruneUpstreamProfiles() {
  const now = Date.now();
  for (const [token, profile] of upstreamProfiles) {
    if (!profile || (now - Number(profile.createdAt || 0)) > UPSTREAM_PROFILE_TTL_MS) {
      upstreamProfiles.delete(token);
    }
  }
  trimMapToMaxEntries(upstreamProfiles, UPSTREAM_PROFILE_MAX_ENTRIES);
}
function issueUpstreamProfile(profile = {}) {
  const safeHeaders = profile && typeof profile.upstreamHeaders === 'object'
    ? Object.fromEntries(Object.entries(profile.upstreamHeaders).filter(([, value]) => typeof value === 'string' && value.trim()))
    : {};
  const userAgent = String(profile.userAgent || '').trim();
  const sourceKey = String(profile.sourceKey || '').trim().toLowerCase();
  const channelSlug = createSlug(profile.channelSlug || profile.slug || '');
  if (!Object.keys(safeHeaders).length && !userAgent && !sourceKey && !channelSlug) return '';
  const token = crypto.randomBytes(12).toString('base64url');
  upstreamProfiles.set(token, { createdAt: Date.now(), upstreamHeaders: safeHeaders, userAgent, sourceKey, channelSlug });
  pruneUpstreamProfiles();
  return token;
}
function getUpstreamProfile(token = '') {
  pruneUpstreamProfiles();
  const key = String(token || '').trim();
  if (!key) return {};
  const profile = upstreamProfiles.get(key);
  if (!profile) return {};
  return {
    upstreamHeaders: { ...(profile.upstreamHeaders || {}) },
    userAgent: String(profile.userAgent || ''),
    sourceKey: String(profile.sourceKey || '').trim().toLowerCase(),
    channelSlug: createSlug(profile.channelSlug || '')
  };
}
