const app = express();
const router = express.Router();
const httpServer = http.createServer(app);
app.disable('x-powered-by');
app.set('views', path.join(__dirname, 'views'));
app.set('view engine', 'ejs');
// Trust Cloudflare proxy
app.set('trust proxy', 1);
if (SocketIOServer) {
  io = new SocketIOServer(httpServer, {
    path: `${BASE_PATH}/socket.io`,
    cors: { origin: '*', methods: ['GET', 'POST'] }
  });
  io.on('connection', socket => {
    const flags = getFeatureFlags();
    const joinedRooms = new Set();
    const socketSessionId = String(socket?.handshake?.query?.sid || '').trim().slice(0, 120);
    const socketForwarded = String(socket?.handshake?.headers?.['x-forwarded-for'] || '').split(',')[0].trim();
    const socketIp = socketForwarded || String(socket?.handshake?.address || '').trim().slice(0, 90);
    if (flags.websocket_live_updates) socket.emit('live:viewers', { ...buildViewerSnapshot(), ts: Date.now() });
    socket.on('channel:join', payload => {
      if (!flags.websocket_live_updates && !flags.websocket_watch_party && !flags.websocket_channel_chat && !flags.websocket_reactions) return;
      const slug = createSlug(payload?.slug || '');
      if (!slug) return;
      const room = `ch:${slug}`;
      socket.join(room);
      joinedRooms.add(room);
    });
    socket.on('channel:leave', payload => {
      const slug = createSlug(payload?.slug || '');
      if (!slug) return;
      const room = `ch:${slug}`;
      socket.leave(room);
      joinedRooms.delete(room);
    });
    socket.on('chat:message', payload => {
      if (!flags.websocket_channel_chat) return;
      const slug = createSlug(payload?.slug || '');
      if (!slug) return;
      const room = `ch:${slug}`;
      const meta = resolveActiveUserMetaBySession(socketSessionId);
      const actorKey = getLiveChatActorKey(meta, { session_id: socketSessionId, ip: socketIp });
      const policy = evaluateLiveChatPolicy(slug, payload?.text || '', actorKey);
      if (!policy.ok) {
        socket.emit('chat:error', { code: policy.code, remaining_ms: policy.remainingMs, message: policy.message });
        return;
      }
      const slowMode = enforceLiveChatSlowMode(slug, actorKey);
      if (!slowMode.ok) {
        socket.emit('chat:error', { code: 'slow_mode', remaining_ms: slowMode.remainingMs });
        return;
      }
      const event = pushLiveChatEvent(slug, { ...payload, user: meta.user_alias || payload?.user || 'User' });
      if (!event) return;
      appendChatAuditLog({
        kind: 'chat',
        slug,
        user: event.user,
        text: event.text,
        session_id: meta.session_id || socketSessionId,
        ip: meta.ip || socketIp,
        fingerprint_hash: meta.fingerprint_hash || '',
        fingerprint_cookie_id: meta.fingerprint_cookie_id || '',
        ua: meta.ua || String(socket?.handshake?.headers?.['user-agent'] || '').slice(0, 220),
        transport: 'socket',
        ts: event.ts
      });
      io.to(room).emit('chat:message', event);
    });
    socket.on('reaction:event', payload => {
      if (!flags.websocket_reactions) return;
      const slug = createSlug(payload?.slug || '');
      if (!slug) return;
      const room = `ch:${slug}`;
      const event = pushLiveReactionEvent(slug, payload);
      if (!event) return;
      const meta = resolveActiveUserMetaBySession(socketSessionId);
      appendChatAuditLog({
        kind: 'reaction',
        slug,
        user: String(payload?.user || 'Anon').slice(0, 40),
        emoji: event.emoji,
        session_id: meta.session_id || socketSessionId,
        ip: meta.ip || socketIp,
        fingerprint_hash: meta.fingerprint_hash || '',
        fingerprint_cookie_id: meta.fingerprint_cookie_id || '',
        ua: meta.ua || String(socket?.handshake?.headers?.['user-agent'] || '').slice(0, 220),
        transport: 'socket',
        ts: event.ts
      });
      io.to(room).emit('reaction:event', event);
    });
    socket.on('watchparty:sync', payload => {
      if (!flags.websocket_watch_party) return;
      const slug = createSlug(payload?.slug || '');
      if (!slug) return;
      const room = `ch:${slug}`;
      const action = String(payload?.action || '').trim().toLowerCase();
      if (!['play', 'pause', 'seek'].includes(action)) return;
      const event = { slug, action, time: Number(payload?.time || 0), ts: Date.now() };
      socket.to(room).emit('watchparty:sync', event);
    });
    socket.on('disconnect', () => {
      joinedRooms.clear();
    });
  });
} else {
  console.warn('socket.io package missing; realtime modules disabled.');
}
router.get('/api/realtime/chat/:slug', (req, res) => {
  const flags = getFeatureFlags();
  if (!flags.websocket_channel_chat) return res.status(404).json({ ok: false, error: 'Chat disabled' });
  const slug = createSlug(req.params.slug || '');
  if (!slug) return res.status(400).json({ ok: false, error: 'Invalid slug' });
  const history = getLiveChatEventsSince(slug, req.query.since || 0);
  return res.json({ ok: true, events: history, ts: Date.now() });
});
router.post('/api/realtime/chat/:slug', express.json({ limit: '50kb' }), (req, res) => {
  const flags = getFeatureFlags();
  if (!flags.websocket_channel_chat) return res.status(404).json({ ok: false, error: 'Chat disabled' });
  const slug = createSlug(req.params.slug || '');
  if (!slug) return res.status(400).json({ ok: false, error: 'Invalid slug' });
  const sessionId = String(req.body?.session_id || req.headers['x-session-id'] || '').trim().slice(0, 120);
  const meta = resolveActiveUserMetaBySession(sessionId);
  const actorKey = getLiveChatActorKey(meta, { session_id: sessionId, ip: getLikelyClientIp(req) });
  const policy = evaluateLiveChatPolicy(slug, req.body?.text || '', actorKey);
  if (!policy.ok) {
    const status = policy.code === 'muted' || policy.code === 'rate_limit' ? 429 : 400;
    return res.status(status).json({ ok: false, error: policy.message, code: policy.code, remaining_ms: policy.remainingMs });
  }
  const slowMode = enforceLiveChatSlowMode(slug, actorKey);
  if (!slowMode.ok) {
    return res.status(429).json({ ok: false, error: 'Slow mode active', code: 'slow_mode', remaining_ms: slowMode.remainingMs });
  }
  const event = pushLiveChatEvent(slug, { ...(req.body || {}), user: meta.user_alias || req.body?.user || 'User' });
  if (!event) return res.status(400).json({ ok: false, error: 'Mesazhi është bosh' });
  appendChatAuditLog({
    kind: 'chat',
    slug,
    user: event.user,
    text: event.text,
    session_id: meta.session_id || sessionId,
    ip: meta.ip || getLikelyClientIp(req),
    fingerprint_hash: meta.fingerprint_hash || '',
    fingerprint_cookie_id: meta.fingerprint_cookie_id || '',
    ua: meta.ua || String(req.headers?.['user-agent'] || '').slice(0, 220),
    transport: 'fallback_api',
    ts: event.ts
  });
  if (io) io.to(`ch:${slug}`).emit('chat:message', event);
  return res.json({ ok: true, event });
});
