function buildAdsTxtContent() {
  const ownership = normalizeSiteOwnershipConfig(appConfig.site_ownership);
  const manualLines = String(ownership.ads_txt_lines || '')
    .split(/\r?\n/g)
    .map(line => String(line || '').trim())
    .filter(Boolean);
  const dedupe = new Set();
  const lines = [];
  for (const row of manualLines) {
    const key = row.toLowerCase();
    if (dedupe.has(key)) continue;
    dedupe.add(key);
    lines.push(row);
  }
  if (!lines.length) return '';
  return `${lines.join('\n')}\n`;
}
function buildAppAdsTxtContent() {
  const ownership = normalizeSiteOwnershipConfig(appConfig.site_ownership);
  const manualLines = String(ownership.app_ads_txt_lines || '')
    .split(/\r?\n/g)
    .map(line => String(line || '').trim())
    .filter(Boolean);
  const dedupe = new Set();
  const lines = [];
  for (const row of manualLines) {
    const key = row.toLowerCase();
    if (dedupe.has(key)) continue;
    dedupe.add(key);
    lines.push(row);
  }
  if (!lines.length) return '';
  return `${lines.join('\n')}\n`;
}
