router.get('/sw.js', (req, res) => {
  const flags = getFeatureFlags();
  const ownership = normalizeSiteOwnershipConfig(appConfig.site_ownership);
  const monetagDomain = String(ownership.monetag_domain || '').trim().toLowerCase();
  const monetagZoneId = Number(ownership.monetag_zone_id || 0);
  const monetagLary = String(ownership.monetag_lary || '');
  const shouldInjectMonetag = ownership.monetag_sw_enabled === true
    && /^[a-z0-9.\-]+\.[a-z]{2,}$/i.test(monetagDomain)
    && Number.isFinite(monetagZoneId)
    && monetagZoneId > 0;
  const shouldServeSw = flags.pwa_enabled || flags.web_push_notifications || shouldInjectMonetag;
  if (!shouldServeSw) return res.status(404).type('text/javascript').send('// PWA disabled');
  const monetagSnippet = shouldInjectMonetag
    ? `\ntry {\n  self.options = { domain: ${JSON.stringify(monetagDomain)}, zoneId: ${Math.floor(monetagZoneId)} };\n  self.lary = ${JSON.stringify(monetagLary)};\n  importScripts('https://${monetagDomain}/act/files/service-worker.min.js?r=sw');\n} catch (_) {}\n`
    : '';
  res.setHeader('Content-Type', 'application/javascript; charset=utf-8');
  res.send(`self.addEventListener('install',e=>{self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(self.clients.claim());});
self.addEventListener('fetch',event=>{
  const req=event.request;
  if(req.method!=='GET') return;
  const url=new URL(req.url);
  if(!url.pathname.startsWith('${BASE_PATH}/')) return;
  if(url.pathname.endsWith('.m3u8')||url.pathname.includes('/proxy/')) return;
  event.respondWith((async()=>{
    try{
      const fresh=await fetch(req);
      const cache=await caches.open('shif-shqip-ui-v1');
      cache.put(req,fresh.clone());
      return fresh;
    }catch{
      const cache=await caches.open('shif-shqip-ui-v1');
      const cached=await cache.match(req);
      return cached||new Response('Offline',{status:503,statusText:'Offline'});
    }
  })());
});
self.addEventListener('push',event=>{
  let data={title:'Shif Shqip',body:'Njoftim i ri',url:'${BASE_PATH}/'};
  try{ data=Object.assign(data, JSON.parse(event.data?.text()||'{}')); }catch{}
  event.waitUntil(self.registration.showNotification(String(data.title||'Shif Shqip').slice(0,80),{
    body:String(data.body||'').slice(0,180),
    icon:'https://phinemi.live/favicon.ico',
    data:{url:data.url||'${BASE_PATH}/',campaignId:data.campaignId||'',openTrackUrl:data.openTrackUrl||''}
  }));
});
self.addEventListener('notificationclick',event=>{
  event.notification.close();
  const data=(event.notification&&event.notification.data)||{};
  const url=data.url||'${BASE_PATH}/';
  const openTrackUrl=data.openTrackUrl||'';
  if(openTrackUrl){
    event.waitUntil(fetch(openTrackUrl,{method:'GET',mode:'no-cors'}).catch(()=>{}));
  }
  event.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(list=>{
    const target=list.find(c=>c.url&&c.url.includes(url));
    if(target) return target.focus();
    return clients.openWindow(url);
  }));
});${monetagSnippet}`);
});
