router.use((req, res, next) => {
  const security = normalizeSecurityHardening(appConfig.security_hardening);
  if (security.enabled && security.strict_headers) {
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'SAMEORIGIN');
    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
    res.setHeader('Permissions-Policy', 'accelerometer=(),camera=(),geolocation=(),gyroscope=(),magnetometer=(),microphone=(),payment=(),usb=()');
    res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
  }
  if (security.enabled && security.block_suspicious_uas) {
    const ua = String(req.headers['user-agent'] || '');
    if (/(sqlmap|nikto|acunetix|dirbuster|nessus|nmap|masscan|zgrab|crawler-test)/i.test(ua)) {
      return res.status(403).send('Blocked');
    }
  }
  if (security.enabled && security.login_rate_limit && req.method === 'POST' && req.path === '/login') {
    const ip = getForwardClientIp(req) || req.ip || 'unknown';
    const allowed = rateLimitAllow(loginRateLimits, ip, 5, 10 * 60 * 1000);
    if (!allowed) return res.status(429).send('Too many login attempts. Try again later.');
  }
  if (security.enabled && security.api_rate_limit && req.path.startsWith('/api/')) {
    if (req.path !== '/api/ping' && req.path !== '/api/viewers') {
      const ip = getForwardClientIp(req) || req.ip || 'unknown';
      const allowed = rateLimitAllow(apiRateLimits, ip, 600, 60 * 1000);
      if (!allowed) return res.status(429).json({ ok: false, error: 'Rate limit exceeded' });
    }
  }
  next();
});

// Session middleware - single instance; Redis store when REDIS_URL is set (PM2 cluster safe)
const sessionConfigBase = {
  secret: SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  proxy: true,
  cookie: {
    maxAge: 24 * 60 * 60 * 1000,
    sameSite: 'lax',
    secure: 'auto',
    httpOnly: true
  }
};
let sessionMiddlewareImpl = (req, res, next) => next();
function sessionMiddleware(req, res, next) {
  return sessionMiddlewareImpl(req, res, next);
}
router.use(sessionMiddleware);

router.use((req, res, next) => {
  if (req.method !== 'GET') return next();
  const routePath = String(req.path || '');
  const isPublicHtmlRoute = !routePath.startsWith('/api/')
    && !routePath.startsWith('/proxy/')
    && !routePath.startsWith('/channel')
    && !routePath.startsWith('/channel-proxy')
    && !routePath.startsWith('/playlist')
    && !routePath.startsWith('/private-playlist')
    && !routePath.startsWith('/app-measurement')
    && !routePath.startsWith('/admin')
    && !routePath.startsWith('/login')
    && !routePath.startsWith('/preview-cache')
    && !/\.(m3u8?|json|ts|m4s|mp4|jpg|png|webp|svg|ico|css|js|map)$/i.test(routePath);
  if (isPublicHtmlRoute) issueBrowseSessionCookie(req, res);
  next();
});

router.use((req, res, next) => {
  if (!shouldRedirectStreamToProxyHost(req)) return next();
  const target = buildStreamProxyRedirectUrl(req);
  if (!target) return next();
  return res.redirect(302, target);
});

// IP Block middleware
router.use((req, res, next) => {
  const ips = getClientIPs(req);
  if ([ips.primary, ips.ipv4, ips.ipv6].some(ip => ip && blockedIps.includes(ip))) {
    return res.status(403).send('Access Denied');
  }
  const abuseTracking = normalizeAbuseTrackingConfig(appConfig.abuse_tracking);
  if (abuseTracking.enabled && abuseTracking.block_by_fingerprint_enabled) {
    const cookieName = String(abuseTracking.cookie_name || 'k1_fp').trim();
    const cookieId = parseCookieValue(req, cookieName).replace(/[^a-zA-Z0-9_\-]/g, '').slice(0, 120);
    if (cookieId) {
      const fpHash = String(fingerprintState.cookies?.[cookieId]?.fingerprint_hash || '').trim().toLowerCase();
      if (fpHash && (abuseTracking.blocked_fingerprints || []).includes(fpHash)) {
        return res.status(403).send('Fingerprint blocked');
      }
    }
  }
  next();
});

function requireLogin(req, res, next) {
  refreshAdminMutableState();
  if (!req.session.loggedIn) {
    if (req.path.startsWith('/api/')) return res.status(401).json({ error: 'Not authenticated' });
    return res.redirect(`${BASE_PATH}/login`);
  }
  next();
}

