function sendLiveChatMessage(){
  if(!currentSlug||!featureFlags.websocket_channel_chat) return;
  const input=document.getElementById('liveChatInput');
  if(!input) return;
  const text=String(input.value||'').trim().slice(0,280);
  if(!text) return;
  if(!chatUsername){ chatUsername=userAlias||('User-'+String(sessionId||'').slice(-4)); }
  const payload={slug:currentSlug,user:chatUsername,text,session_id:sessionId};
  trackGa('chat_message_sent',{channel_slug:currentSlug||'',transport:(socket&&socket.connected)?'socket':'fallback',text_len:text.length});
  if(socket&&socket.connected){
    socket.emit('chat:message',payload);
  }else{
    fetch(BASE+'/api/realtime/chat/'+encodeURIComponent(currentSlug),{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify(payload)
    })
      .then(r=>r.json().then(data=>({ok:r.ok,data})))
      .then(({ok,data})=>{
        if(!ok||!data||data.ok===false){
          const code=String(data&&data.code||'');
          const remain=Math.max(0, Math.ceil(Number(data&&data.remaining_ms||0)/1000));
          if(code==='slow_mode') setStatus('warn','Slow mode aktiv. Prit '+remain+'s.');
          else if(code==='muted') setStatus('err','Je mute në chat edhe '+remain+'s.');
          else if(code==='rate_limit') setStatus('warn','Shumë mesazhe në 1 minutë.');
          else if(code==='blocked_link') setStatus('warn','Linket nuk lejohen në chat.');
          else if(code==='blocked_word') setStatus('warn','Mesazhi ka fjalë të bllokuara.');
          return;
        }
        if(data&&data.event) appendLiveChatMessage(data.event);
      })
      .catch(()=>{});
  }
  input.value='';
}
