function setupAndroidTvMode(){
  if(!enableAndroidTvUi) return;
  document.body.classList.add('android-tv-ui');
  const cards=Array.from(document.querySelectorAll('.ch-card'));
  if(!cards.length) return;
  let idx=0;
  const focusCard=(n)=>{ idx=Math.max(0,Math.min(cards.length-1,n)); cards[idx].focus(); cards[idx].scrollIntoView({block:'nearest',inline:'nearest'}); };
  cards.forEach(card=>{ card.setAttribute('tabindex','0'); });
  focusCard(0);
  document.addEventListener('keydown',e=>{
    if(e.key==='ArrowRight'){e.preventDefault();focusCard(idx+1);}
    else if(e.key==='ArrowLeft'){e.preventDefault();focusCard(idx-1);}
    else if(e.key==='ArrowDown'){e.preventDefault();focusCard(idx+3);}
    else if(e.key==='ArrowUp'){e.preventDefault();focusCard(idx-3);}
    else if(e.key==='Enter'){e.preventDefault();cards[idx]?.click();}
  });
}
async function registerPwaAndPush(){
  let deferredPrompt=null;
  const installBtn=document.getElementById('pwaInstallBtn');
  if(enablePwa&&installBtn){
    installBtn.style.display='inline-flex';
    installBtn.title='Install app';
    window.addEventListener('beforeinstallprompt',(event)=>{
      event.preventDefault();
      deferredPrompt=event;
      installBtn.innerHTML='<i class="fas fa-download"></i>';
    });
    installBtn.onclick=async()=>{
      trackGa('pwa_install_click',{page_type:pageType||'unknown'});
      if(deferredPrompt){
        try{
          deferredPrompt.prompt();
          await deferredPrompt.userChoice.catch(()=>{});
          deferredPrompt=null;
        }catch{}
        return;
      }
      if(/iphone|ipad|ipod/i.test(navigator.userAgent||'')){
        alert('Në iPhone/iPad: Safari -> Share -> Add to Home Screen.');
      }else{
        alert('Nëse Install nuk del automatikisht, hap menu-n e browser-it dhe zgjidh "Install app".');
      }
    };
  }
  if(enablePwa&&('serviceWorker' in navigator)){
    try{ await navigator.serviceWorker.register(BASE+'/sw.js',{scope:BASE+'/'}); }catch{}
  }
  if(!enablePush||!('serviceWorker' in navigator)||!('PushManager' in window)) return;
  const btn=document.getElementById('pushSubscribeBtn');
  if(!btn) return;
  btn.style.display='inline-flex';
  btn.onclick=async()=>{
    try{
      const perm=await Notification.requestPermission();
      if(perm!=='granted') return alert('Push permission u refuzua.');
      const keyRes=await fetch(BASE+'/api/push/public-key',{cache:'no-store'});
      const keyData=await keyRes.json();
      if(!keyData||!keyData.publicKey) throw new Error('public key missing');
      const reg=await navigator.serviceWorker.register(BASE+'/sw.js',{scope:BASE+'/'});
      const toUint8=(base64)=>Uint8Array.from(atob(base64.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));
      const sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:toUint8(keyData.publicKey)});
      await fetch(BASE+'/api/push/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(sub)});
      alert('Push notifications u aktivizuan.');
    }catch(err){
      alert('Gabim push: '+(err&&err.message?err.message:'unknown'));
    }
  };
}
