const PLAYER_MODAL = PLAYER_MODAL_SPLIT;

function buildCards(channels, options = {}) {
  const redirectKoolOnMain = !!options.redirectKoolOnMain;
  const categoryKeyOverride = String(options.categoryKeyOverride || '').trim();
  const pageType = String(options.pageType || '').trim().toLowerCase();
  const adSettings = normalizeAdSnippetConfig(appConfig.ad_snippets);
  const allowNativeByPage = (pageType === 'main' && adSettings.show_banner_on_main !== false)
    || (pageType.startsWith('category') && adSettings.show_banner_on_category !== false);
  const enableNativeCards = adSettings.enabled === true
    && adSettings.grid_native_enabled === true
    && allowNativeByPage
    && Number(adSettings.grid_native_every || 0) > 0;
  const nativeEvery = Math.max(0, parseInt(adSettings.grid_native_every, 10) || 0);
  const nativeSnippets = [String(adSettings.banner_html || '').trim(), ...(Array.isArray(adSettings.banner_html_list) ? adSettings.banner_html_list : [])]
    .map(v => String(v || '').trim())
    .filter(Boolean);
  const rows = [];
  let idx = 0;
  let nativeCardsInserted = 0;
  for (const [slug, ch] of Object.entries(channels)) {
    const isKoolLike = ch.type === 'kool' || ch.type === 'kool_lokke' || getChannelSourceKey(ch) === 'kool_lokke';
    const sc = ch.type === 'sport' ? 'sport' : (ch.type === 'nimi' ? 'nimi' : (isKoolLike ? 'kool' : ''));
    const enc = ch.encrypted ? '<div class="ch-enc"><i class="fas fa-lock"></i></div>' : '';
    const typeIcon = ch.type === 'sport' ? 'futbol' : (ch.type === 'nimi' ? 'shield-alt' : (isKoolLike ? 'satellite-dish' : 'tv'));
    const logo = String(ch.logo || '').trim();
    const safeLogo = logo.replace(/"/g, '&quot;');
    const thumbMedia = safeLogo
      ? `<img src="${safeLogo}" alt="${ch.name}" style="width:100%;height:100%;object-fit:cover" onerror="this.remove()">`
      : `<i class="fas fa-${typeIcon}"></i>`;
    const safeSlug = String(slug || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    const safeName = String(ch.name || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    const sourceKey = getChannelSourceKey(ch);
    const derivedCategoryKey = categoryKeyOverride
      || (ch.customCategoryId ? `custom:${createSlug(ch.customCategoryId)}` : (ch.customCat ? `custom_builtin:${ch.customCat}` : (ch.type === 'sport' ? 'builtin:sports' : (ch.type === 'nimi' ? 'builtin:nimi' : 'builtin:all'))));
    const safeCategoryKey = String(derivedCategoryKey || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    let openAction = `openPlayerGuarded('${safeSlug}','${safeName}','${safeCategoryKey}','${String(sourceKey || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'")}')`;
    const isKoolCard = getChannelSourceKey(ch) === 'kool' || /^kool_/i.test(String(slug || ''));
    if (redirectKoolOnMain && isKoolCard) {
      const redirectPath = buildKoolRedirectPath(slug, ch);
      if (redirectPath) {
        const safeRedirectPath = String(redirectPath).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
        openAction = `window.location.assign('${safeRedirectPath}')`;
      }
    }
    const openActionAttr = openAction.replace(/"/g, '&quot;');
    rows.push(`<div class="ch-card ${sc}" data-slug="${slug}" data-cat="${safeCategoryKey}" data-source="${sourceKey}" onclick="${openActionAttr}">
<div class="ch-thumb">${thumbMedia}<div class="ch-live">LIVE</div>${enc}
<div class="viewer-count" style="display:none;position:absolute;bottom:6px;left:6px;background:rgba(0,0,0,.75);color:var(--sport);font-size:.55rem;font-weight:700;padding:2px 6px;border-radius:4px;align-items:center;gap:3px"><i class="fas fa-eye" style="font-size:.5rem"></i> <span>0</span></div>
</div>
<div class="ch-info"><div class="ch-name">${ch.name}</div></div>
<div class="ch-actions" onclick="event.stopPropagation()">
<button class="ch-btn ch-btn-play" onclick="${openActionAttr}"><i class="fas fa-play"></i> Shiko</button>
<button class="fav-btn" data-slug="${slug}" onclick="toggleFavorite('${slug}',event)" style="background:none;border:1px solid var(--border);color:var(--muted);border-radius:6px;padding:4px 8px;cursor:pointer;font-size:.7rem;transition:all .2s"><i class="far fa-heart"></i></button>
</div></div>`);
    idx += 1;
    // Insert one native "Sponsored" card per DISTINCT ad zone. A single ad zone
    // can only be filled once per page (its invoke.js targets a fixed container
    // id), so repeating one zone across slots leaves the extras empty. Cap the
    // slots to the number of distinct snippets so every rendered ad actually
    // fills — add more zones in the banner snippet list to get more ad slots.
    if (enableNativeCards && nativeEvery > 0 && idx % nativeEvery === 0 && nativeCardsInserted < nativeSnippets.length) {
      const pick = nativeSnippets[nativeCardsInserted % nativeSnippets.length];
      const encoded = Buffer.from(String(pick || ''), 'utf8').toString('base64');
      rows.push(`<div class="ch-card native-ad-card" data-native-ad="1"><div class="native-ad-head"><i class="fas fa-bullhorn"></i> Sponsored</div><div class="native-ad-body" data-ad-snippet="${encoded}"></div></div>`);
      nativeCardsInserted += 1;
    }
  }
  return rows.join('');
}

function visibleChannels(src) {
  const out = {};
  for (const [slug, channel] of Object.entries(src || {})) {
    if (!channel || typeof channel !== 'object') continue;
    if (appConfig.visible_channels?.[slug] === false) continue;
    if (!isSourceAccessibleNow(getChannelSourceKey(channel))) continue;
    out[slug] = channel;
  }
  return out;
}

function resolveM3uGroupTitle(slug, ch = {}) {
  const channel = ch && typeof ch === 'object' ? ch : {};
  const safeSlug = createSlug(slug || '') || String(slug || '').trim();
  const customCatId = String(channel.customCategoryId || '').trim();
  if (customCatId) {
    const catKey = createSlug(customCatId) || customCatId;
    const cat = customCategories[catKey] || customCategories[customCatId];
    if (cat && cat.name) return String(cat.name).trim();
  }
  const customCat = String(channel.customCat || '').trim().toLowerCase();
  if (customCat === 'sport') return 'Sport';
  if (customCat === 'nimi') return 'Nimi';
  for (const cat of Object.values(customCategories || {})) {
    if (!cat || typeof cat !== 'object') continue;
    if (Array.isArray(cat.channels) && cat.channels.includes(safeSlug)) {
      return String(cat.name || 'Kategori').trim();
    }
  }
  if (channel.type === 'sport') return 'Sport';
  if (channel.type === 'nimi') return 'Nimi';
  if (channel.type === 'kool' || channel.type === 'kool_lokke') return String(channel.koolCategory || 'Kool').trim();
  return 'TV';
}
function makeM3U(channels, name, publicBaseUrl = '', req = null) {
  const lines = [`#EXTM3U\n#PLAYLIST:${name}\n`];
  let lastGroupTitle = '';
  for (const [slug, ch] of Object.entries(channels)) {
    const { groupTitle, groupLogo } = resolveM3uGroupMeta(slug, ch);
    if (groupTitle !== lastGroupTitle) {
      lines.push(`#EXTGRP:${groupTitle}`);
      if (groupLogo) lines.push(`#GROUPlogo:${groupLogo}`);
      lastGroupTitle = groupTitle;
    }
    const epgId = String(ch.epgId || ch.id || '').trim();
    const logo = String(ch.logo || '').trim() || groupLogo;
    const groupLogoAttr = groupLogo ? ` group-logo="${groupLogo}"` : '';
    lines.push(`#EXTINF:-1 tvg-id="${epgId}" tvg-name="${ch.name}" tvg-logo="${logo}" group-title="${groupTitle}"${groupLogoAttr},${ch.name}`);
    const streamPath = buildSignedChannelPath(slug, { req, channel: ch });
    const streamUrl = publicBaseUrl ? `${publicBaseUrl}${streamPath}` : streamPath;
    lines.push(streamUrl + '\n');
  }
  return lines.join('\n');
}
function normalizePlaylistDeliveryMode(value = '') {
  const mode = String(value || '').trim().toLowerCase();
  return mode === 'restream' ? 'restream' : 'private';
}
function normalizePlaylistEndpointMode(value = '') {
  const mode = String(value || '').trim().toLowerCase();
  if (mode === 'app_measurement' || mode === 'app-measurement' || mode === 'appmeasurement') return 'app_measurement';
  return 'playlist';
}
function resolvePlaylistEndpointMode(playlist = {}) {
  return normalizePlaylistEndpointMode(
    playlist.endpoint_mode
      || playlist.playlist_endpoint_mode
      || playlist.route_mode
      || playlist.app_measurement_mode
      || 'playlist'
  );
}
function normalizePlaylistUserAgentMode(value = '') {
  const mode = String(value || '').trim().toLowerCase();
  if (mode === 'allowlist' || mode === 'allowed' || mode === 'restricted') return 'allowlist';
  return 'all';
}
function parsePlaylistUserAgentList(value = '') {
  const rows = Array.isArray(value) ? value : String(value || '').split(/\r?\n|[,;]+/g);
  return Array.from(new Set(rows
    .map(item => String(item || '').trim())
    .filter(Boolean)
    .slice(0, 80)));
}
function normalizePlaylistChannelOrder(selectedSlugs, requestedOrderRaw) {
  const normalizedSelection = remapChannelSlugList(
    Array.from(new Set(
      (Array.isArray(selectedSlugs) ? selectedSlugs : (selectedSlugs ? [selectedSlugs] : []))
        .map(v => String(v || '').trim())
        .filter(Boolean)
    )),
    allCombined
  );
  try {
    const requestedOrder = JSON.parse(String(requestedOrderRaw || '[]'));
    if (Array.isArray(requestedOrder) && requestedOrder.length) {
      const allowed = new Set(normalizedSelection);
      const ordered = [];
      for (const slug of requestedOrder) {
        const normalizedSlug = resolveChannelSlugReference(String(slug || '').trim(), allCombined)
          || (allCombined[String(slug || '').trim()] ? String(slug || '').trim() : '');
        if (!normalizedSlug || !allowed.has(normalizedSlug)) continue;
        if (!ordered.includes(normalizedSlug)) ordered.push(normalizedSlug);
      }
      for (const slug of normalizedSelection) {
        if (!ordered.includes(slug)) ordered.push(slug);
      }
      return ordered;
    }
  } catch {
    // Ignore invalid order payload and use checkbox selection order.
  }
  return normalizedSelection;
}
function normalizePlaylistCategories(raw = {}) {
  const out = {};
  if (!raw || typeof raw !== 'object') return out;
  for (const [rawId, cat] of Object.entries(raw)) {
    const id = createSlug(rawId || cat?.id || '');
    if (!id || !cat || typeof cat !== 'object') continue;
    const name = String(cat.name || '').trim();
    if (!name) continue;
    const channels = Array.isArray(cat.channels)
      ? Array.from(new Set(cat.channels.map(s => createSlug(String(s || '').trim())).filter(Boolean)))
      : [];
    out[id] = {
      id,
      name,
      logo: normalizeHttpUrl(cat.logo || ''),
      order: Math.max(0, parseInt(cat.order, 10) || 0),
      channels
    };
  }
  return out;
}
function parsePlaylistCategoriesFromBody(body = {}, allowedSlugs = new Set(), existingCategories = {}) {
  const existing = normalizePlaylistCategories(existingCategories);
  const categories = {};
  const rawIds = Array.isArray(body.playlist_cat_id) ? body.playlist_cat_id : (body.playlist_cat_id ? [body.playlist_cat_id] : []);
  const rawNames = Array.isArray(body.playlist_cat_name) ? body.playlist_cat_name : (body.playlist_cat_name ? [body.playlist_cat_name] : []);
  const rawLogos = Array.isArray(body.playlist_cat_logo) ? body.playlist_cat_logo : (body.playlist_cat_logo ? [body.playlist_cat_logo] : []);
  const rawOrders = Array.isArray(body.playlist_cat_order) ? body.playlist_cat_order : (body.playlist_cat_order ? [body.playlist_cat_order] : []);
  for (let i = 0; i < rawNames.length; i += 1) {
    const name = String(rawNames[i] || '').trim();
    if (!name) continue;
    const id = createSlug(String(rawIds[i] || name)) || createSlug(name);
    if (!id) continue;
    categories[id] = {
      id,
      name,
      logo: normalizeHttpUrl(String(rawLogos[i] || '').trim() || existing[id]?.logo || ''),
      order: Math.max(0, parseInt(rawOrders[i], 10) || existing[id]?.order || i + 1),
      channels: Array.isArray(existing[id]?.channels) ? existing[id].channels.slice() : []
    };
  }
  for (const slug of allowedSlugs) {
    const field = `playlist_channel_category_${slug}`;
    const catId = createSlug(String(body[field] || '').trim());
    if (!catId || !categories[catId]) continue;
    if (!categories[catId].channels.includes(slug)) categories[catId].channels.push(slug);
  }
  return normalizePlaylistCategories(categories);
}
function syncPlaylistMasterChannels(playlist = {}) {
  const categories = normalizePlaylistCategories(playlist.categories || {});
  const fromCategories = new Set();
  for (const cat of Object.values(categories)) {
    for (const slug of (cat.channels || [])) {
      if (allCombined[slug]) fromCategories.add(slug);
    }
  }
  const existing = Array.isArray(playlist.channels) ? playlist.channels : [];
  const uncategorized = existing.filter(slug => {
    if (!allCombined[slug]) return false;
    for (const cat of Object.values(categories)) {
      if ((cat.channels || []).includes(slug)) return false;
    }
    return true;
  });
  return Array.from(new Set([...fromCategories, ...uncategorized]));
}
function saveCustomPlaylist(playlistId, playlist) {
  customPlaylists[playlistId] = playlist;
  saveJSON(PLAYLISTS_FILE, customPlaylists);
}
function buildPlaylistCategoryChannelOrder(playlist = {}, channelsMap = {}) {
  const categories = normalizePlaylistCategories(playlist.categories || {});
  const orderedCats = Object.values(categories).sort((a, b) => (a.order - b.order) || a.name.localeCompare(b.name));
  const masterOrder = Array.isArray(playlist.channels)
    ? playlist.channels.filter(s => channelsMap[s])
    : Object.keys(channelsMap);
  const seen = new Set();
  const out = [];
  for (const cat of orderedCats) {
    for (const slug of (cat.channels || [])) {
      if (!channelsMap[slug] || seen.has(slug)) continue;
      out.push(slug);
      seen.add(slug);
    }
  }
  for (const slug of masterOrder) {
    if (!seen.has(slug)) out.push(slug);
  }
  return out;
}
function resolvePlaylistM3uGroupMeta(slug, ch = {}, playlist = {}) {
  const categories = normalizePlaylistCategories(playlist.categories || {});
  for (const cat of Object.values(categories)) {
    if ((cat.channels || []).includes(slug)) {
      return { groupTitle: cat.name, groupLogo: cat.logo || '' };
    }
  }
  return { groupTitle: 'Pa kategori', groupLogo: '' };
}
function buildGroupedChannelCheckboxGrid(options = {}) {
  const channels = options.channels && typeof options.channels === 'object' ? options.channels : allCombined;
  const selected = options.selected instanceof Set
    ? options.selected
    : new Set(Array.isArray(options.selected) ? options.selected : []);
  const checkboxName = String(options.checkboxName || 'playlist_channels');
  const idPrefix = String(options.idPrefix || 'pc');
  const sorted = Object.entries(channels).sort((a, b) => String(a[1]?.name || '').localeCompare(String(b[1]?.name || '')));
  const groupedBySource = new Map();
  for (const [slug, channel] of sorted) {
    const sourceKey = getChannelSourceKey(channel);
    if (!groupedBySource.has(sourceKey)) groupedBySource.set(sourceKey, []);
    groupedBySource.get(sourceKey).push([slug, channel]);
  }
  const sourceOrder = [
    ...SOURCE_KEYS,
    ...Array.from(groupedBySource.keys()).filter(key => !SOURCE_KEYS.includes(key)).sort()
  ];
  const sourceFilterOptions = sourceOrder.map(sourceKey => {
    const entries = groupedBySource.get(sourceKey) || [];
    if (!entries.length) return '';
    const sourceLabel = SOURCE_LABELS[sourceKey] || sourceKey;
    return `<option value="${sourceKey}">${sourceLabel} (${entries.length})</option>`;
  }).filter(Boolean).join('');
  const categoryOptions = Array.isArray(options.categoryOptions) ? options.categoryOptions : [];
  const categorySelectHtml = (slug, currentCatId = '') => categoryOptions.length
    ? `<select name="playlist_channel_category_${slug}" class="form-input playlist-cat-select" style="margin:0;max-width:150px;padding:4px 6px;font-size:.65rem" onchange="event.stopPropagation()">
<option value="">Pa kategori</option>
${categoryOptions.map(cat => `<option value="${escapeHtmlAttr(cat.id)}" ${currentCatId === cat.id ? 'selected' : ''}>${escapeHtml(cat.name)}</option>`).join('')}
</select>`
    : '';
  const boxes = sourceOrder.map(sourceKey => {
    const entries = groupedBySource.get(sourceKey) || [];
    if (!entries.length) return '';
    const sourceLabel = SOURCE_LABELS[sourceKey] || sourceKey;
    const rows = entries.map(([slug, ch]) => {
      const color = ch.type === 'sport' ? 'var(--sport)' : (ch.type === 'nimi' ? 'var(--purple)' : 'var(--accent)');
      const icon = ch.type === 'sport' ? 'futbol' : (ch.type === 'nimi' ? 'shield-alt' : 'tv');
      const checked = selected.has(slug) ? 'checked' : '';
      const searchText = `${String(ch.name || '')} ${sourceLabel} ${sourceKey}`.toLowerCase().replace(/"/g, '&quot;');
      const currentCatId = createSlug(String(options.channelCategoryMap?.[slug] || ''));
      return `<div class="channel-checkbox-item" data-source="${sourceKey}" data-name="${searchText}">
<input type="checkbox" name="${checkboxName}" value="${slug}" ${checked} id="${idPrefix}_${slug}">
<label for="${idPrefix}_${slug}" style="cursor:pointer;display:flex;align-items:center;gap:6px;flex:1">
<span style="color:${color}"><i class="fas fa-${icon}"></i></span><span>${escapeHtml(ch.name || slug)}</span>
<span style="margin-left:auto;color:var(--muted);font-size:.62rem">${escapeHtml(sourceLabel)}</span>
</label>${categorySelectHtml(slug, currentCatId)}</div>`;
    }).join('');
    return `<div class="channel-source-header" data-source-header="${sourceKey}">
<span><i class="fas fa-layer-group" style="color:var(--accent)"></i> ${escapeHtml(sourceLabel)}</span>
<span class="badge" style="font-size:.65rem">${entries.length}</span>
</div>${rows}`;
  }).join('');
  const channelNameMap = Object.fromEntries(sorted.map(([slug, ch]) => [slug, ch?.name || slug]));
  return { html: boxes, sourceFilterOptions, channelNameMap };
}
const PLAYLIST_ORDER_CLIENT_SCRIPT = `
function initPlaylistChannelOrder(config){
  const channelNames=config.channelNames||{};
  let selectedOrder=Array.isArray(config.initialOrder)?config.initialOrder.slice():[];
  const checkboxName=config.checkboxName||'playlist_channels';
  const orderInput=document.getElementById(config.orderInputId);
  const orderList=document.getElementById(config.orderListId);
  const form=config.formId?document.getElementById(config.formId):null;
  const scope=form||document;
  let dragIdx=null;
  function esc(v){return String(v||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
  function bindOrderItemEvents(){
    if(!orderList) return;
    orderList.querySelectorAll('.playlist-order-item').forEach(el=>{
      el.addEventListener('dragstart',e=>{
        dragIdx=Number(el.dataset.idx);
        el.classList.add('dragging');
        if(e.dataTransfer){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragIdx));}
      });
      el.addEventListener('dragend',()=>{el.classList.remove('dragging');dragIdx=null;});
      el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('drag-over');if(e.dataTransfer) e.dataTransfer.dropEffect='move';});
      el.addEventListener('dragleave',()=>el.classList.remove('drag-over'));
      el.addEventListener('drop',e=>{
        e.preventDefault();
        el.classList.remove('drag-over');
        const from=dragIdx;
        const to=Number(el.dataset.idx);
        if(from===null||Number.isNaN(to)||from===to) return;
        const item=selectedOrder[from];
        selectedOrder.splice(from,1);
        selectedOrder.splice(to,0,item);
        renderSelectedOrder();
      });
    });
    orderList.querySelectorAll('.po-move-up').forEach(btn=>{
      btn.addEventListener('click',()=>moveSelected(Number(btn.dataset.idx),-1));
    });
    orderList.querySelectorAll('.po-move-down').forEach(btn=>{
      btn.addEventListener('click',()=>moveSelected(Number(btn.dataset.idx),1));
    });
    orderList.querySelectorAll('.po-remove').forEach(btn=>{
      btn.addEventListener('click',()=>removeSelected(String(btn.dataset.slug||'')));
    });
  }
  function renderSelectedOrder(){
    if(!orderList) return;
    if(!selectedOrder.length){
      orderList.innerHTML='<p style="color:var(--muted);padding:10px 0">Asnjë kanal i zgjedhur.</p>';
      if(orderInput) orderInput.value='[]';
      return;
    }
    orderList.innerHTML=selectedOrder.map(function(slug,idx){
      return '<div class="playlist-card playlist-order-item" draggable="true" data-idx="'+idx+'" data-slug="'+esc(slug)+'" style="padding:8px 10px;gap:8px;cursor:grab">'
        +'<div style="color:var(--muted);padding-right:4px"><i class="fas fa-grip-vertical"></i></div>'
        +'<div style="flex:1;min-width:0">'
        +'<div style="font-size:.78rem;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+(idx+1)+'. '+esc(channelNames[slug]||slug)+'</div>'
        +'<div style="font-size:.62rem;color:var(--muted);font-family:monospace">'+esc(slug)+'</div>'
        +'</div>'
        +'<div style="display:flex;gap:6px">'
        +'<button type="button" class="a-btn a-btn-primary po-move-up" data-idx="'+idx+'" style="padding:4px 8px;font-size:.68rem"'+(idx===0?' disabled':'')+'><i class="fas fa-arrow-up"></i></button>'
        +'<button type="button" class="a-btn a-btn-primary po-move-down" data-idx="'+idx+'" style="padding:4px 8px;font-size:.68rem"'+(idx===selectedOrder.length-1?' disabled':'')+'><i class="fas fa-arrow-down"></i></button>'
        +'<button type="button" class="a-btn a-btn-red po-remove" data-slug="'+esc(slug)+'" style="padding:4px 8px;font-size:.68rem"><i class="fas fa-times"></i></button>'
        +'</div></div>';
    }).join('');
    if(orderInput) orderInput.value=JSON.stringify(selectedOrder);
    bindOrderItemEvents();
  }
  function syncSelectedOrderFromChecks(){
    const checked=Array.from(scope.querySelectorAll('input[name="'+checkboxName+'"]:checked')).map(i=>i.value);
    const set=new Set(checked);
    selectedOrder=selectedOrder.filter(slug=>set.has(slug));
    checked.forEach(slug=>{if(!selectedOrder.includes(slug)) selectedOrder.push(slug);});
    renderSelectedOrder();
  }
  function moveSelected(index,delta){
    const to=index+delta;
    if(to<0||to>=selectedOrder.length) return;
    const item=selectedOrder[index];
    selectedOrder[index]=selectedOrder[to];
    selectedOrder[to]=item;
    renderSelectedOrder();
  }
  function removeSelected(slug){
    selectedOrder=selectedOrder.filter(s=>s!==slug);
    scope.querySelectorAll('input[name="'+checkboxName+'"]').forEach(cb=>{if(cb.value===slug) cb.checked=false;});
    renderSelectedOrder();
  }
  scope.querySelectorAll('input[name="'+checkboxName+'"]').forEach(ch=>ch.addEventListener('change',syncSelectedOrderFromChecks));
  if(form) form.addEventListener('submit',syncSelectedOrderFromChecks);
  renderSelectedOrder();
  return {syncSelectedOrderFromChecks,moveSelected,removeSelected,renderSelectedOrder};
}
`;
function resolvePlaylistUserAgentPolicy(playlist = {}) {
  return {
    mode: normalizePlaylistUserAgentMode(playlist.user_agent_mode || playlist.ua_mode),
    list: parsePlaylistUserAgentList(playlist.user_agent_list || playlist.user_agents || playlist.user_agent_rules || playlist.ua_rules || '')
  };
}
function detectPlaylistClientType(req) {
  const ua = String(req?.headers?.['user-agent'] || '').toLowerCase();
  if (!ua) return 'unknown';
  if (/(python|curl|wget|httpclient|go-http-client|okhttp|axios|node-fetch|postman|insomnia|libwww|java|ffmpeg|libav|vlc\/lua|streamlink|yt-dlp)/i.test(ua)) {
    return 'vps/server';
  }
  if (/(tivimate|ott navigator|smart[- ]?stb|smart[- ]?iptv|ssiptv|xciptv|televizo|iptv smarters|set[- ]?top|android tv|google tv|aft[bmns]|bravia|web0s\.tv|tizen|roku|apple tv|hbbtv|tv safari)/i.test(ua)) {
    return 'tv';
  }
  if (/(iphone|android.*mobile|windows phone|mobile|huawei|samsung|xiaomi|redmi|oneplus|oppo|vivo)/i.test(ua)) {
    return 'phone';
  }
  if (/(ipad|tablet|sm-t|tab)/i.test(ua)) {
    return 'tablet';
  }
  if (/(windows nt|macintosh|x11; linux|cros)/i.test(ua)) {
    return 'desktop';
  }
  return 'other';
}
function isPlaylistUserAgentAllowed(req, playlist = {}) {
  const policy = resolvePlaylistUserAgentPolicy(playlist);
  if (policy.mode !== 'allowlist') return { ok: true, mode: policy.mode, matched: '' };
  const uaRaw = String(req?.headers?.['user-agent'] || '').trim();
  const ua = uaRaw.toLowerCase();
  if (!ua) return { ok: false, mode: policy.mode, matched: '', reason: 'ua_missing' };
  for (const rule of policy.list) {
    const safe = String(rule || '').trim();
    if (!safe) continue;
    if (ua.includes(safe.toLowerCase())) return { ok: true, mode: policy.mode, matched: safe };
  }
  return { ok: false, mode: policy.mode, matched: '', reason: 'ua_not_allowed' };
}
function buildRestreamPlaylistSlugAlias(slug = '') {
  const raw = String(slug || '').trim().toLowerCase();
  if (!raw) return '';
  return raw.replace(/[_-]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function buildPlaylistChannelRouteSegment(slug = '', deliveryMode = 'private') {
  const normalizedMode = normalizePlaylistDeliveryMode(deliveryMode);
  if (normalizedMode !== 'restream') return encodeURIComponent(String(slug || '').trim());
  const alias = buildRestreamPlaylistSlugAlias(slug) || String(slug || '').trim();
  return encodeURIComponent(alias).replace(/%20/g, ' ');
}
function normalizePlaylistSlugCandidate(value = '') {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .replace(/[._-]+/g, ' ')
    .trim();
}
function resolvePlaylistAllowedChannelSlug(playlist = {}, requestedSlug = '') {
  const requestedRaw = String(requestedSlug || '').trim();
  if (!requestedRaw) return '';
  const requestedExact = requestedRaw.toLowerCase();
  const requestedNormalized = normalizePlaylistSlugCandidate(requestedRaw);
  const allowed = Array.isArray(playlist.channels) ? playlist.channels : [];
  for (const candidateRaw of allowed) {
    const candidate = String(candidateRaw || '').trim();
    if (!candidate) continue;
    if (candidate.toLowerCase() === requestedExact) return candidate;
    const alias = buildRestreamPlaylistSlugAlias(candidate);
    if (alias && alias === requestedExact) return candidate;
    const candidateNormalized = normalizePlaylistSlugCandidate(candidate);
    if (candidateNormalized && candidateNormalized === requestedNormalized) return candidate;
    const aliasNormalized = normalizePlaylistSlugCandidate(alias);
    if (aliasNormalized && aliasNormalized === requestedNormalized) return candidate;
  }
  return '';
}
function makePrivatePlaylistM3U(playlistId, channels, name, publicBaseUrl = '', vodList = [], options = {}) {
  const deliveryMode = normalizePlaylistDeliveryMode(options.deliveryMode || options.mode);
  const endpointMode = normalizePlaylistEndpointMode(options.endpointMode || options.pathMode || options.routeMode);
  const playlist = options.playlist && typeof options.playlist === 'object' ? options.playlist : {};
  const usePlaylistCategories = Object.keys(normalizePlaylistCategories(playlist.categories || {})).length > 0;
  const safePlaylistId = createSlug(playlistId) || String(playlistId || '').trim();
  const routeBase = endpointMode === 'app_measurement'
    ? `${BASE_PATH}/app-measurement/collect/${encodeURIComponent(safePlaylistId)}`
    : `${BASE_PATH}/playlist/${encodeURIComponent(safePlaylistId)}`;
  const streamExt = endpointMode === 'app_measurement' ? 'json' : 'm3u8';
  const lines = [`#EXTM3U\n#PLAYLIST:${name}\n`];
  const channelOrder = usePlaylistCategories
    ? buildPlaylistCategoryChannelOrder(playlist, channels || {})
    : (Array.isArray(options.channelOrder) ? options.channelOrder : Object.keys(channels || {}));
  let lastGroupTitle = '';
  for (const slug of channelOrder) {
    const ch = (channels || {})[slug];
    if (!ch || typeof ch !== 'object') continue;
    const { groupTitle, groupLogo } = usePlaylistCategories
      ? resolvePlaylistM3uGroupMeta(slug, ch, playlist)
      : resolveM3uGroupMeta(slug, ch);
    if (groupTitle !== lastGroupTitle) {
      lines.push(`#EXTGRP:${groupTitle}`);
      if (groupLogo) lines.push(`#GROUPlogo:${groupLogo}`);
      lastGroupTitle = groupTitle;
    }
    const epgId = String(ch.epgId || ch.id || '').trim();
    const logo = String(ch.logo || '').trim() || groupLogo;
    const groupLogoAttr = groupLogo ? ` group-logo="${groupLogo}"` : '';
    lines.push(`#EXTINF:-1 tvg-id="${epgId}" tvg-name="${ch.name}" tvg-logo="${logo}" group-title="${groupTitle}"${groupLogoAttr},${ch.name}`);
    const streamPath = `${routeBase}/${buildPlaylistChannelRouteSegment(slug, deliveryMode)}.${streamExt}`;
    lines.push(publicBaseUrl ? `${publicBaseUrl}${streamPath}` : streamPath);
    lines.push('');
  }
  // VOD entries removed from private playlists

  return lines.join('\n');
}

