router.get('/proxy/sub', async (req, res) => {
  const url = decrypt(req.query.id);
  if (!url) return res.status(403).send('Forbidden');
  const profileToken = String(req.query.hp || '').trim();
  const upstreamProfile = getUpstreamProfile(profileToken);
  const sourceKey = String(upstreamProfile.sourceKey || '').trim().toLowerCase();
  const channelSlug = createSlug(upstreamProfile.channelSlug || '');
  const originCheck = validateSourceOrigin(req, sourceKey);
  if (!originCheck.ok) return res.status(403).send('Origin blocked');
  const cookieCheck = validatePlaybackCookieForSource(req, sourceKey);
  if (!cookieCheck.ok) return res.status(403).send('Playback cookie required');
  const geoCheck = await validateSourceGeo(req, sourceKey);
  if (!geoCheck.ok) return res.status(451).send('Geo blocked');
  await proxyManifest(url, req, res, 'sub', { profileToken, upstreamProfile });
});

router.get('/proxy/seg', async (req, res) => {
  const segUrl = decrypt(req.query.id);
  if (!segUrl) return res.status(403).send('Forbidden');
  const profileToken = String(req.query.hp || '').trim();
  const upstreamProfile = getUpstreamProfile(profileToken);
  const sourceKey = String(upstreamProfile.sourceKey || '').trim().toLowerCase();
  const channelSlug = createSlug(upstreamProfile.channelSlug || '');
  const originCheck = validateSourceOrigin(req, sourceKey);
  if (!originCheck.ok) return res.status(403).send('Origin blocked');
  const cookieCheck = validatePlaybackCookieForSource(req, sourceKey);
  if (!cookieCheck.ok) return res.status(403).send('Playback cookie required');
  const geoCheck = await validateSourceGeo(req, sourceKey);
  if (!geoCheck.ok) return res.status(451).send('Geo blocked');
  const protection = getPlaybackProtectionSettings();
  if (protection.segment_rate_limit_enabled && isSourceFlagEnabled(protection.segment_rate_limit_apply_sources, sourceKey)) {
    const ip = getLikelyClientIp(req);
    const bucketKey = `${sourceKey}|${ip}`;
    const allowed = rateLimitAllow(proxySegRateLimits, bucketKey, protection.segment_rate_limit_per_minute, 60 * 1000);
    if (!allowed) return res.status(429).send('Segment rate limit exceeded');
  }
  const nimiProtection = getNimiProtectionSettings();
  const hotCacheEnabled = (isNimiSourceKey(sourceKey) && nimiProtection.restream_enabled === true)
    || isSourceFlagEnabled(protection.hot_segment_cache_enabled_sources, sourceKey);
  const cacheKey = getNimiRestreamCacheKey(segUrl, upstreamProfile);
  if (hotCacheEnabled && !req.headers.range) {
    hotSegmentStore.pruneMemoryCache(Number(protection.hot_segment_cache_max_mb || 256) * 1024 * 1024);
    const cached = await hotSegmentStore.getCachedEntry(cacheKey);
    if (cached && Number(cached.expiresAt || 0) > Date.now()) {
      recordProxyBandwidth(Number(cached.size || 0), channelSlug);
      res.setHeader('X-Hot-Segment-Store', hotSegmentStore.getStoreMode());
      return sendNimiRestreamSegment(res, cached, { hit: true, sourceKey, singleflight: 'HIT' });
    }
  }
  try {
    const response = await axios.get(segUrl, {
      responseType: 'stream',
      timeout: 25000,
      maxRedirects: 5,
      httpAgent: KEEPALIVE_HTTP_AGENT,
      httpsAgent: KEEPALIVE_HTTPS_AGENT,
      headers: buildUpstreamHeaders(req, segUrl, true, upstreamProfile),
      validateStatus: status => status >= 200 && status < 500
    });
    if (response.status >= 400) return res.status(response.status).send('Segment error');
    setProxyCorsHeaders(res);
    setProxyPassthroughHeaders(res, response.headers || {});
    if (!res.getHeader('X-Segment-Singleflight')) res.setHeader('X-Segment-Singleflight', 'STREAM');
    res.setHeader('Cache-Control', 'public, max-age=6, stale-while-revalidate=20');
    if (!response.headers?.['accept-ranges']) res.setHeader('Accept-Ranges', 'bytes');
    const contentLength = parseInt(response.headers?.['content-length'], 10);
    if (Number.isFinite(contentLength) && contentLength > 0) {
      recordProxyBandwidth(contentLength, channelSlug);
    }
    res.status(response.status);
    let countedBytes = 0;
    response.data.on('data', chunk => {
      if (Number.isFinite(contentLength) && contentLength > 0) return;
      countedBytes += Buffer.byteLength(chunk || Buffer.alloc(0));
    });
    response.data.on('error', () => {
      if (!res.headersSent) res.status(502).end();
      else res.end();
    });
    response.data.on('end', () => {
      if (!(Number.isFinite(contentLength) && contentLength > 0) && countedBytes > 0) {
        recordProxyBandwidth(countedBytes, channelSlug);
      }
    });
    response.data.pipe(res);
  } catch (e) {
    console.error('Proxy seg error:', e.message);
    res.status(502).send('Segment error');
  }
});

