router.post('/api/account/session', async (req, res) => {
  const settings = normalizeFirebaseAuthConfig(appConfig.firebase_auth);
  if (settings.enabled !== true) return res.status(404).json({ ok: false, error: 'Firebase auth disabled' });
  const idToken = String(req.body?.id_token || req.body?.idToken || '').trim();
  const deviceId = String(req.body?.device_id || req.body?.deviceId || '').trim().slice(0, 120);
  const sessionId = String(req.body?.session_id || req.body?.sessionId || '').trim().slice(0, 120);
  if (!idToken) return res.status(400).json({ ok: false, error: 'id_token required' });
  if (!deviceId) return res.status(400).json({ ok: false, error: 'device_id required' });
  const verified = await verifyFirebaseIdTokenWithGoogle(idToken);
  if (!verified.ok || !verified.user?.uid) return res.status(401).json({ ok: false, error: 'Invalid firebase token' });
  if (verified.user.is_google !== true) {
    return res.status(403).json({ ok: false, error: 'only_google_allowed' });
  }
  const profile = ensureFirebaseUserProfile(verified.user.uid, verified.user);
  if (!profile) return res.status(500).json({ ok: false, error: 'Failed to resolve user profile' });
  const limit = enforceFirebaseDeviceLimit(profile, deviceId);
  if (!limit.ok) return res.status(429).json({ ok: false, error: limit.code, max_devices: limit.max_devices || 0, active_devices: limit.active_devices || 0 });
  updateFirebaseDeviceSession(profile, {
    device_id: deviceId,
    session_id: sessionId,
    ua: req.headers['user-agent'] || '',
    ip: getLikelyClientIp(req)
  });
  profile.last_seen_at = Date.now();
  firebaseUserAccountsDirty = true;
  const accountSessionToken = `acct_${crypto.randomBytes(20).toString('hex')}`;
  firebaseAccountSessions.set(accountSessionToken, {
    uid: profile.uid,
    device_id: deviceId,
    session_id: sessionId,
    created_at: Date.now(),
    last_seen: Date.now(),
    expires_at: Date.now() + FIREBASE_ACCOUNT_SESSION_TTL_MS
  });
  firebaseAccountSessionsDirty = true;
  persistFirebaseUserAccountsState();
  persistFirebaseAccountSessionsState();
  return res.json({
    ok: true,
    account_session_token: accountSessionToken,
    expires_in_sec: Math.floor(FIREBASE_ACCOUNT_SESSION_TTL_MS / 1000),
    profile: buildFirebaseAccountPublicSummary(profile),
    settings: {
      max_devices_enabled: settings.max_devices_enabled === true,
      max_devices: settings.max_devices,
      trial_enabled: settings.trial_enabled === true,
      trial_days: settings.trial_days,
      trial_max_uses: settings.trial_max_uses,
      referral_reward_days: settings.referral_reward_days,
      referral_referred_bonus_days: settings.referral_referred_bonus_days
    }
  });
});
router.post('/api/account/logout', (req, res) => {
  const session = getFirebaseAccountSession(req);
  if (session) {
    firebaseAccountSessions.delete(session.token);
    firebaseAccountSessionsDirty = true;
    const profile = firebaseUserAccountsState?.users?.[session.uid];
    if (profile && profile.device_sessions && session.device_id) {
      delete profile.device_sessions[String(session.device_id || '').trim()];
      firebaseUserAccountsDirty = true;
      persistFirebaseUserAccountsState();
    }
    persistFirebaseAccountSessionsState();
  }
  return res.json({ ok: true });
});
