router.post('/api/block-ip', requireLoginOrToken, (req, res) => {
  const { ip } = req.body;
  if (ip && !blockedIps.includes(ip)) { blockedIps.push(ip); saveJSON(BLOCKED_IPS_FILE, blockedIps); }
  // Also kick active users with this IP
  for (const [sid, data] of activeUsers) {
    if (data.ip === ip || data.ipv4 === ip || data.ipv6 === ip) activeUsers.delete(sid);
  }
  emitViewerSnapshot(true);
  res.json({ ok: true });
});

router.post('/api/unblock-ip', requireLoginOrToken, (req, res) => {
  const { ip } = req.body;
  blockedIps = blockedIps.filter(i => i !== ip);
  saveJSON(BLOCKED_IPS_FILE, blockedIps);
  res.json({ ok: true });
});
router.post('/api/block-fingerprint', requireLoginOrToken, (req, res) => {
  const hash = String(req.body?.fingerprint_hash || '').trim().toLowerCase().replace(/[^a-f0-9]/g, '').slice(0, 64);
  if (!hash) return res.status(400).json({ ok: false, error: 'fingerprint_hash required' });
  const cfg = normalizeAbuseTrackingConfig(appConfig.abuse_tracking);
  if (!cfg.blocked_fingerprints.includes(hash)) cfg.blocked_fingerprints.push(hash);
  appConfig.abuse_tracking = normalizeAbuseTrackingConfig(cfg);
  saveJSON(CONFIG_FILE, appConfig);
  for (const [sid, data] of activeUsers) {
    if (String(data.fingerprintHash || '').trim().toLowerCase() === hash) activeUsers.delete(sid);
  }
  emitViewerSnapshot(true);
  res.json({ ok: true, blocked: appConfig.abuse_tracking.blocked_fingerprints.length });
});
router.post('/api/unblock-fingerprint', requireLoginOrToken, (req, res) => {
  const hash = String(req.body?.fingerprint_hash || '').trim().toLowerCase().replace(/[^a-f0-9]/g, '').slice(0, 64);
  if (!hash) return res.status(400).json({ ok: false, error: 'fingerprint_hash required' });
  const cfg = normalizeAbuseTrackingConfig(appConfig.abuse_tracking);
  cfg.blocked_fingerprints = (cfg.blocked_fingerprints || []).filter(item => item !== hash);
  appConfig.abuse_tracking = normalizeAbuseTrackingConfig(cfg);
  saveJSON(CONFIG_FILE, appConfig);
  res.json({ ok: true, blocked: appConfig.abuse_tracking.blocked_fingerprints.length });
});
router.get('/api/abuse/export.csv', requireLoginOrToken, (req, res) => {
  const type = String(req.query.type || 'devices').trim().toLowerCase();
  const lines = [];
  if (type === 'cookies') {
    lines.push(['cookie_id', 'fingerprint_hash', 'first_seen', 'last_seen', 'pings', 'last_ip', 'last_session_id'].join(','));
    for (const row of Object.values(fingerprintState.cookies || {})) {
      lines.push([
        csvEscape(row.cookie_id || ''),
        csvEscape(row.fingerprint_hash || ''),
        Number(row.first_seen || 0),
        Number(row.last_seen || 0),
        Number(row.pings || 0),
        csvEscape(row.last_ip || ''),
        csvEscape(row.last_session_id || '')
      ].join(','));
    }
  } else if (type === 'events') {
    lines.push(['ts', 'fingerprint_hash', 'cookie_id', 'ip', 'session_id', 'channel_slug', 'source'].join(','));
    for (const row of fingerprintState.events || []) {
      lines.push([
        Number(row.ts || 0),
        csvEscape(row.fingerprint_hash || ''),
        csvEscape(row.cookie_id || ''),
        csvEscape(row.ip || ''),
        csvEscape(row.session_id || ''),
        csvEscape(row.channel_slug || ''),
        csvEscape(row.source || '')
      ].join(','));
    }
  } else {
    lines.push(['fingerprint_hash', 'first_seen', 'last_seen', 'pings', 'ip_count', 'ips', 'cookie_count', 'last_channel_slug'].join(','));
    for (const row of Object.values(fingerprintState.devices || {})) {
      const ipList = Object.keys(row.ips || {}).slice(0, 32).join('|');
      lines.push([
        csvEscape(row.hash || ''),
        Number(row.first_seen || 0),
        Number(row.last_seen || 0),
        Number(row.pings || 0),
        countObjectKeys(row.ips || {}),
        csvEscape(ipList),
        countObjectKeys(row.cookies || {}),
        csvEscape(row.last_channel_slug || '')
      ].join(','));
    }
  }
  res.setHeader('Content-Type', 'text/csv; charset=utf-8');
  res.setHeader('Content-Disposition', `attachment; filename="abuse_${type}_${Date.now()}.csv"`);
  res.send(`\uFEFF${lines.join('\n')}`);
});

// Custom channels API
router.post('/api/custom-channel/add', requireLoginOrToken, async (req, res) => {
  const { name, url, category, logo } = req.body;
  const youtubeUrl = normalizeUrlExact(req.body?.youtube_url || req.body?.youtubeUrl || '');
  const embedUrl = normalizeUrlExact(req.body?.embed_url || req.body?.embedUrl || '');
  const backupUrls = normalizeBackupUrls([
    ...(Array.isArray(req.body?.backup_urls) ? req.body.backup_urls : []),
    req.body?.backup_url_1,
    req.body?.backup_url_2,
    req.body?.backup_url_3,
    req.body?.backup_links
  ]);
  const upstream = parseCustomChannelUpstreamInput(req.body || {});
  if (!name || !url || !['tv','sport','nimi'].includes(category)) return res.json({ ok: false, error: 'Invalid data' });
  const normalizedCategory = normalizeCustomCategoryValue(category);
  const sourceKeyToEnable = normalizedCategory === 'sport' ? 'custom_sport' : (normalizedCategory === 'nimi' ? 'custom_nimi' : 'custom_tv');
  ensureSourcesEnabled([sourceKeyToEnable]);
  const imported = addCustomChannelEntryDetailed(category, name, url, {
    logo,
    backup_urls: backupUrls,
    youtube_url: youtubeUrl,
    embed_url: embedUrl,
    user_agent: upstream.user_agent,
    upstream_headers: upstream.upstream_headers,
    referer: req.body?.referer || req.body?.upstream_referer,
    origin: req.body?.origin || req.body?.upstream_origin,
    cookie: req.body?.cookie || req.body?.upstream_cookie,
    x_forwarded_for: req.body?.x_forwarded_for || req.body?.upstream_x_forwarded_for
  });
  if (!imported) return res.json({ ok: false, error: 'Ky kanal ekziston tashmë në këtë kategori' });
  renumberCustomChannels(category);
  saveJSON(CUSTOM_CH_FILE, customChannels);
  await updateDatabases();
  res.json({ ok: true, slug: imported.slug });
});

router.post('/api/custom-channel/delete', requireLoginOrToken, async (req, res) => {
  const { name, category, slug } = req.body;
  if (!customChannels[category]) return res.json({ ok: false });
  const targetSlug = createSlug(String(slug || ''));
  const before = customChannels[category].length;
  customChannels[category] = customChannels[category].filter(ch => {
    if (targetSlug) return createSlug(ch.slug || '') !== targetSlug;
    return ch.name !== name;
  });
  if (before === customChannels[category].length) return res.json({ ok: false, error: 'Kanali nuk u gjet' });
  renumberCustomChannels(category);
  saveJSON(CUSTOM_CH_FILE, customChannels);
  await updateDatabases();
  res.json({ ok: true });
});

router.post('/api/custom-channel/update', requireLoginOrToken, async (req, res) => {
  const rawCategory = String(req.body?.category || '').trim().toLowerCase();
  if (!isValidCustomCategoryValue(rawCategory)) return res.status(400).json({ ok: false, error: 'Kategori e pavlefshme' });
  const category = normalizeCustomCategoryValue(rawCategory);
  const slug = createSlug(String(req.body?.slug || ''));
  const name = String(req.body?.name || '').trim();
  const url = normalizeUrl(req.body?.url || '') || normalizeUrlExact(req.body?.url || '');
  const logoRaw = String(req.body?.logo || '').trim();
  const logo = normalizeUrl(logoRaw) || logoRaw;
  const youtubeUrl = normalizeUrlExact(req.body?.youtube_url || req.body?.youtubeUrl || '');
  const embedUrl = normalizeUrlExact(req.body?.embed_url || req.body?.embedUrl || '');
  const backupUrls = normalizeBackupUrls([
    ...(Array.isArray(req.body?.backup_urls) ? req.body.backup_urls : []),
    req.body?.backup_url_1,
    req.body?.backup_url_2,
    req.body?.backup_url_3,
    req.body?.backup_links
  ]);
  if (!slug || !name || !url) return res.status(400).json({ ok: false, error: 'Të dhëna të pavlefshme' });
  if (!Array.isArray(customChannels[category])) customChannels[category] = [];
  const idx = customChannels[category].findIndex(item => createSlug(item.slug || '') === slug);
  if (idx === -1) return res.status(404).json({ ok: false, error: 'Kanali nuk u gjet' });
  const duplicate = customChannels[category].some((item, itemIdx) => itemIdx !== idx && normalizeUrlExact(item.url || '') === url);
  if (duplicate) return res.status(409).json({ ok: false, error: 'Ky URL ekziston tashmë në këtë kategori' });
  const upstream = parseCustomChannelUpstreamInput(req.body || {});
  customChannels[category][idx] = {
    ...customChannels[category][idx],
    name,
    url,
    logo,
    backup_urls: backupUrls,
    youtube_url: youtubeUrl,
    embed_url: embedUrl,
    user_agent: upstream.user_agent,
    upstream_headers: upstream.upstream_headers
  };
  renumberCustomChannels(category);
  saveJSON(CUSTOM_CH_FILE, customChannels);
  await updateDatabases();
  res.json({ ok: true });
});

router.post('/api/custom-channel/reorder', requireLoginOrToken, async (req, res) => {
  const rawCategory = String(req.body?.category || '').trim().toLowerCase();
  if (!isValidCustomCategoryValue(rawCategory)) return res.status(400).json({ ok: false, error: 'Kategori e pavlefshme' });
  const category = normalizeCustomCategoryValue(rawCategory);
  const slug = createSlug(String(req.body?.slug || ''));
  const direction = String(req.body?.direction || '').trim().toLowerCase();
  if (!slug || !['up', 'down'].includes(direction)) return res.status(400).json({ ok: false, error: 'Kërkesë e pavlefshme' });
  if (!Array.isArray(customChannels[category])) customChannels[category] = [];
  const list = customChannels[category];
  const index = list.findIndex(item => createSlug(item.slug || '') === slug);
  if (index === -1) return res.status(404).json({ ok: false, error: 'Kanali nuk u gjet' });
  const target = direction === 'up' ? index - 1 : index + 1;
  if (target < 0 || target >= list.length) return res.json({ ok: true, moved: false });
  const current = list[index];
  list[index] = list[target];
  list[target] = current;
  renumberCustomChannels(category);
  saveJSON(CUSTOM_CH_FILE, customChannels);
  await updateDatabases();
  res.json({ ok: true, moved: true });
});

router.post('/api/custom-channel/move', requireLoginOrToken, async (req, res) => {
  const rawFromCategory = String(req.body?.from_category || '').trim().toLowerCase();
  const rawToCategory = String(req.body?.to_category || '').trim().toLowerCase();
  if (!isValidCustomCategoryValue(rawFromCategory) || !isValidCustomCategoryValue(rawToCategory)) {
    return res.status(400).json({ ok: false, error: 'Kërkesë e pavlefshme' });
  }
  const fromCategory = normalizeCustomCategoryValue(rawFromCategory);
  const toCategory = normalizeCustomCategoryValue(rawToCategory);
  const slug = createSlug(String(req.body?.slug || ''));
  if (!slug) {
    return res.status(400).json({ ok: false, error: 'Kërkesë e pavlefshme' });
  }
  if (fromCategory === toCategory) return res.json({ ok: true, moved: false });
  if (!Array.isArray(customChannels[fromCategory])) customChannels[fromCategory] = [];
  if (!Array.isArray(customChannels[toCategory])) customChannels[toCategory] = [];
  const sourceList = customChannels[fromCategory];
  const idx = sourceList.findIndex(item => createSlug(item.slug || '') === slug);
  if (idx === -1) return res.status(404).json({ ok: false, error: 'Kanali nuk u gjet' });
  const [moved] = sourceList.splice(idx, 1);
  const duplicateUrl = customChannels[toCategory].some(item => normalizeUrlExact(item.url || '') === normalizeUrlExact(moved.url || ''));
  if (duplicateUrl) {
    sourceList.splice(idx, 0, moved);
    return res.status(409).json({ ok: false, error: 'Ky kanal ekziston në kategorinë target' });
  }
  customChannels[toCategory].push({ ...moved, order: (customChannels[toCategory].length + 1) });
  renumberCustomChannels(fromCategory);
  renumberCustomChannels(toCategory);
  saveJSON(CUSTOM_CH_FILE, customChannels);
  await updateDatabases();
  res.json({ ok: true, moved: true });
});

router.post('/api/custom-channel/clear', requireLoginOrToken, async (req, res) => {
  const category = String(req.body?.category || 'all').trim().toLowerCase();
  if (category === 'all') {
    customChannels = { tv: [], sport: [], nimi: [] };
  } else if (['tv', 'sport', 'nimi'].includes(category)) {
    if (!customChannels[category]) customChannels[category] = [];
    customChannels[category] = [];
  } else {
    return res.status(400).json({ ok: false, error: 'Kategori e pavlefshme' });
  }
  saveJSON(CUSTOM_CH_FILE, customChannels);
  await updateDatabases();
  const total = (customChannels.tv || []).length + (customChannels.sport || []).length + (customChannels.nimi || []).length;
  res.json({ ok: true, category, totalCustomChannels: total });
});

router.post('/api/channel/check', requireLoginOrToken, async (req, res) => {
  const inputUrl = normalizeUrl(req.body?.url || '');
  if (!inputUrl) return res.status(400).json({ ok: false, error: 'URL e pavlefshme' });
  const upstream = parseCustomChannelUpstreamInput(req.body || {});
  const upstreamProfile = {
    userAgent: upstream.user_agent,
    upstreamHeaders: upstream.upstream_headers
  };
  const startedAt = Date.now();
  try {
    const response = await axios.get(inputUrl, {
      timeout: 10000,
      maxRedirects: 5,
      responseType: 'text',
      httpAgent: KEEPALIVE_HTTP_AGENT,
      httpsAgent: KEEPALIVE_HTTPS_AGENT,
      headers: buildUpstreamHeaders(req, inputUrl, false, upstreamProfile),
      validateStatus: status => status >= 200 && status < 500
    });
    const durationMs = Date.now() - startedAt;
    res.json({
      ok: true,
      reachable: response.status < 400,
      status: response.status,
      finalUrl: response.request?.res?.responseUrl || inputUrl,
      durationMs
    });
  } catch (error) {
    const durationMs = Date.now() - startedAt;
    res.json({
      ok: true,
      reachable: false,
      status: 0,
      error: error.message,
      finalUrl: inputUrl,
      durationMs
    });
  }
});

