router.post('/api/admin/channel/update', requireLoginOrToken, express.json({ limit: '60kb' }), async (req, res) => {
  const slug = createSlug(String(req.body?.slug || ''));
  const channel = slug ? allCombined[slug] : null;
  if (!slug || !channel) return res.status(404).json({ ok: false, error: 'Kanali nuk u gjet' });
  const name = String(req.body?.name || '').trim();
  const url = normalizeUrlExact(req.body?.url || '');
  const backupUrls = normalizeBackupUrls(req.body?.backup_urls || []);
  if (!name || !url) return res.status(400).json({ ok: false, error: 'Emri dhe URL janë të detyrueshme' });

  const sourceKey = getChannelSourceKey(channel);
  let mode = 'custom_override';

  if (sourceKey === 'custom_tv' || sourceKey === 'custom_sport' || sourceKey === 'custom_nimi') {
    const category = sourceKey === 'custom_sport' ? 'sport' : (sourceKey === 'custom_nimi' ? 'nimi' : 'tv');
    const list = Array.isArray(customChannels[category]) ? customChannels[category] : [];
    const idx = list.findIndex(item => createSlug(item.slug || '') === slug);
    if (idx === -1) return res.status(404).json({ ok: false, error: 'Kanali custom nuk u gjet' });
    customChannels[category][idx] = {
      ...customChannels[category][idx],
      name,
      url,
      backup_urls: backupUrls
    };
    renumberCustomChannels(category);
    saveJSON(CUSTOM_CH_FILE, customChannels);
    mode = 'custom_direct';
  } else if (sourceKey === 'open_source' || sourceKey === 'nimi') {
    const filePath = sourceKey === 'nimi' ? NIMI_M3U_FILE : OPEN_SOURCE_M3U_FILE;
    const result = mutateM3UChannelsByName(filePath, channel.name, (group) => {
      const first = group.entries[0] || {};
      const nextEntries = [{
        name,
        url,
        meta: String(first?.meta || '').trim(),
        headers: first?.headers && typeof first.headers === 'object' ? first.headers : {},
        userAgent: String(first?.userAgent || '').trim()
      }];
      for (const backupUrl of backupUrls) {
        if (backupUrl === url) continue;
        nextEntries.push({
          name,
          url: backupUrl,
          meta: String(first?.meta || '').trim(),
          headers: first?.headers && typeof first.headers === 'object' ? first.headers : {},
          userAgent: String(first?.userAgent || '').trim()
        });
      }
      return { name, entries: nextEntries };
    });
    if (!result.ok) return res.status(400).json({ ok: false, error: 'Nuk u përditësua source playlist' });
    mode = 'source_playlist_direct';
  } else {
    const category = String(channel.type || '').trim().toLowerCase() === 'sport'
      ? 'sport'
      : (String(channel.type || '').trim().toLowerCase() === 'nimi' ? 'nimi' : 'tv');
    const inserted = addCustomChannelEntryDetailed(category, name, url, {
      backup_urls: backupUrls,
      logo: String(channel.logo || '').trim()
    });
    if (!inserted) {
      return res.status(409).json({ ok: false, error: 'Ky URL ekziston tashmë te custom channels' });
    }
    if (!appConfig.visible_channels || typeof appConfig.visible_channels !== 'object') appConfig.visible_channels = {};
    appConfig.visible_channels[slug] = false;
    saveJSON(CUSTOM_CH_FILE, customChannels);
    saveJSON(CONFIG_FILE, appConfig);
    mode = 'source_to_custom_override';
  }

  await updateDatabases();
  return res.json({ ok: true, mode });
});
router.post('/api/admin/channel/delete', requireLoginOrToken, express.json({ limit: '30kb' }), async (req, res) => {
  const slug = createSlug(String(req.body?.slug || ''));
  const channel = slug ? allCombined[slug] : null;
  if (!slug || !channel) return res.status(404).json({ ok: false, error: 'Kanali nuk u gjet' });

  const sourceKey = getChannelSourceKey(channel);
  const channelName = String(channel.name || '').trim();
  let mode = 'hard_delete';
  let sourceChanged = false;

  if (sourceKey === 'custom_tv' || sourceKey === 'custom_sport' || sourceKey === 'custom_nimi') {
    const category = sourceKey === 'custom_sport' ? 'sport' : (sourceKey === 'custom_nimi' ? 'nimi' : 'tv');
    const before = Array.isArray(customChannels[category]) ? customChannels[category].length : 0;
    customChannels[category] = (customChannels[category] || []).filter(item => createSlug(item.slug || '') !== slug);
    renumberCustomChannels(category);
    sourceChanged = before !== customChannels[category].length;
    if (sourceChanged) saveJSON(CUSTOM_CH_FILE, customChannels);
  } else if (sourceKey === 'open_source' || sourceKey === 'nimi') {
    const filePath = sourceKey === 'nimi' ? NIMI_M3U_FILE : OPEN_SOURCE_M3U_FILE;
    const result = mutateM3UChannelsByName(filePath, channelName, () => null);
    sourceChanged = result.ok;
  } else {
    mode = 'hard_delete_with_block';
    appConfig.deleted_channel_keys = normalizeDeletedChannelKeys([
      ...(Array.isArray(appConfig.deleted_channel_keys) ? appConfig.deleted_channel_keys : []),
      normalizeChannelMergeKey(channelName)
    ]);
    sourceChanged = true;
    saveJSON(CONFIG_FILE, appConfig);
  }

  if (mode !== 'hard_delete_with_block') {
    appConfig.deleted_channel_keys = normalizeDeletedChannelKeys(
      (Array.isArray(appConfig.deleted_channel_keys) ? appConfig.deleted_channel_keys : []).filter(item => item !== normalizeChannelMergeKey(channelName))
    );
    saveJSON(CONFIG_FILE, appConfig);
  }

  purgeChannelEverywhere(slug, { channelName });
  await updateDatabases();
  return res.json({ ok: true, mode, source_changed: sourceChanged });
});

