function buildMobileAdsConfigPayload() {
  const cfg = normalizeMobileAdMobConfig(appConfig.mobile_admob);
  const payload = {
    ok: true,
    platform: 'mobile_wrapper_only',
    web_supported: false,
    note: 'AdMob unit IDs are for Android/iOS SDK wrappers, not direct website rendering.',
    config: {
      enabled: cfg.enabled === true,
      app_id: cfg.app_id || '',
      banner_ad_unit_id: cfg.banner_ad_unit_id || '',
      interstitial_ad_unit_id: cfg.interstitial_ad_unit_id || '',
      app_open_ad_unit_id: cfg.app_open_ad_unit_id || '',
      fullscreen_format: cfg.fullscreen_format || 'INTERSTITIAL',
      auto_show_app_open_on_start: cfg.auto_show_app_open_on_start === true
    }
  };
  payload.enabled = payload.config.enabled;
  payload.app_id = payload.config.app_id;
  payload.banner_ad_unit_id = payload.config.banner_ad_unit_id;
  payload.interstitial_ad_unit_id = payload.config.interstitial_ad_unit_id;
  payload.app_open_ad_unit_id = payload.config.app_open_ad_unit_id;
  payload.fullscreen_format = payload.config.fullscreen_format;
  payload.auto_show_app_open_on_start = payload.config.auto_show_app_open_on_start;
  payload.appId = payload.config.app_id;
  payload.bannerAdUnitId = payload.config.banner_ad_unit_id;
  payload.interstitialAdUnitId = payload.config.interstitial_ad_unit_id;
  payload.appOpenAdUnitId = payload.config.app_open_ad_unit_id;
  payload.autoShowAppOpenOnStart = payload.config.auto_show_app_open_on_start;
  payload.updated_at = new Date().toISOString();
  payload.base_path = BASE_PATH;
  return payload;
}

