router.post('/api/integrations/kool/refresh-signature', requireLoginOrToken, async (req, res) => {
  if (!ensureSourceAvailableJson(res, 'kool')) return;
  try {
    const clientIp = normalizePublicClientIp(req.body?.ip) || normalizePublicClientIp(req.query?.ip);
    const signature = await koolService.signatureManager.refreshSignature({
      clientIp,
      userAgent: req.headers['user-agent'] || ''
    });
    res.json({
      ok: true,
      clientIp: clientIp || '',
      signature: signature ? `${signature.slice(0, 24)}...` : 'None'
    });
  } catch (error) {
    res.status(500).json({ ok: false, error: error.message });
  }
});

