router.get('/api/integrations/kool-lokke/channels', requireLoginOrToken, (req, res) => {
  if (!ensureSourceAvailableJson(res, 'kool_lokke')) return;
  const category = String(req.query.category || '').trim();
  const search = String(req.query.search || '').trim().toLowerCase();
  const limitRaw = parseInt(req.query.limit, 10);
  const offsetRaw = parseInt(req.query.offset, 10);
  const limit = Number.isFinite(limitRaw) ? Math.min(Math.max(limitRaw, 1), 20000) : 5000;
  const offset = Number.isFinite(offsetRaw) ? Math.max(offsetRaw, 0) : 0;
  let channels = category ? koolLokkeService.getChannelsByCategoryFromCache(category) : koolLokkeService.getAllChannels();
  channels = mergeChannelVariantList(channels, { mergeByCategory: true, maxBackups: 16, appendLokkeTag: true });
  if (search) {
    channels = channels.filter(ch => String(ch.name).toLowerCase().includes(search) || String(ch.category).toLowerCase().includes(search));
  }
  channels = channels.sort((a, b) => {
    const byCat = String(a.category || '').localeCompare(String(b.category || ''));
    if (byCat !== 0) return byCat;
    return String(a.name || '').localeCompare(String(b.name || ''));
  });
  const total = channels.length;
  const page = channels.slice(offset, offset + limit);
  res.json({ ok: true, total, offset, limit, channels: page });
});

