router.post('/api/integrations/kool/import', requireLoginOrToken, async (req, res) => {
  if (!ensureSourceAvailableJson(res, 'kool')) return;
  const rawIds = Array.isArray(req.body.channel_ids) ? req.body.channel_ids : (req.body.channel_ids ? [req.body.channel_ids] : []);
  const ids = rawIds.map(v => String(v || '').trim()).filter(Boolean).slice(0, 50000);
  if (!ids.length) return res.status(400).json({ ok: false, error: 'No channels selected' });
  const requestedTarget = String(req.body.target_category || 'auto').trim().toLowerCase();
  let imported = 0;
  let skipped = 0;

  for (const id of ids) {
    const channel = koolService.getChannelById(id);
    if (!channel) {
      skipped += 1;
      continue;
    }
    const targetCategory = requestedTarget === 'auto'
      ? guessKoolTargetCategory(channel.category)
      : normalizeCustomCategoryValue(requestedTarget);
    const targetSourceKey = targetCategory === 'sport' ? 'custom_sport' : (targetCategory === 'nimi' ? 'custom_nimi' : 'custom_tv');
    ensureSourcesEnabled([targetSourceKey]);
    if (addCustomChannelEntry(targetCategory, channel.name, channel.url, { logo: channel.logo || '' })) imported += 1;
    else skipped += 1;
  }

  if (imported > 0) {
    saveJSON(CUSTOM_CH_FILE, customChannels);
    await updateDatabases();
  }

  res.json({ ok: true, imported, skipped, requested: ids.length });
});

