function hashTextFastLegacyServer(text) {
  const str = String(text || '');
  let h1 = 0xdeadbeef ^ str.length;
  let h2 = 0x41c6ce57 ^ str.length;
  for (let i = 0; i < str.length; i += 1) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return ((h2 >>> 0).toString(16) + (h1 >>> 0).toString(16)).slice(0, 32).toLowerCase();
}
router.post('/api/parental/verify', (req, res) => {
  const flags = normalizeFeatureFlags(appConfig.feature_flags);
  if (flags.parental_controls_pin !== true) return res.json({ ok: true, enabled: false, valid: true });
  const expected = String(flags.parental_pin_hash || '').trim().toLowerCase();
  if (!expected) return res.json({ ok: true, enabled: true, valid: false, reason: 'pin_not_set' });
  const pin = String(req.body?.pin || '').trim();
  if (!/^\d{4}$/.test(pin)) return res.json({ ok: true, enabled: true, valid: false, reason: 'invalid_format' });
  const secureHash = crypto.createHash('sha256').update(`pin:${pin}:${SESSION_SECRET}`).digest('hex').toLowerCase();
  const legacyHash = hashTextFastLegacyServer(pin);
  const legacySha256Hash = crypto.createHash('sha256').update(pin).digest('hex').toLowerCase();
  const validRaw = /^\d{4}$/.test(expected) && expected === pin;
  const valid = expected === secureHash || expected === legacyHash || expected === legacySha256Hash || validRaw;
  return res.json({ ok: true, enabled: true, valid });
});

/** Service Worker that fetches A3/fastly from the viewer's IP (not CF/VPS egress). */
router.get('/a3sw.js', (req, res) => {
  res.setHeader('Content-Type', 'application/javascript; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('Service-Worker-Allowed', '/');
  res.send(`/* A3 client-IP HLS proxy SW */
const SW_PREFIX = ${JSON.stringify(BASE_PATH + '/a3sw')};
function decodeRh(rhRaw) {
  try {
    const raw = String(rhRaw || '').trim();
    if (!raw) return null;
    const pad = '='.repeat((4 - (raw.length % 4)) % 4);
    const b64 = (raw + pad).replace(/-/g, '+').replace(/_/g, '/');
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    const parsed = JSON.parse(new TextDecoder().decode(bytes));
    if (!parsed || typeof parsed !== 'object') return null;
    return parsed;
  } catch (_) { return null; }
}
function buildHeaders(rh) {
  const out = { Accept: '*/*', 'Accept-Encoding': 'identity' };
  if (rh && typeof rh === 'object') {
    for (const [k, v] of Object.entries(rh)) {
      const name = String(k || '').trim();
      const value = String(v || '').trim();
      if (!name || !value) continue;
      if (/^(host|connection|content-length|accept-encoding|transfer-encoding)$/i.test(name)) continue;
      if (/^x-forwarded-for$/i.test(name) && /^(127\\.0\\.0\\.1|::1|localhost)$/i.test(value)) continue;
      out[name] = value;
    }
  }
  if (!Object.keys(out).some((k) => k.toLowerCase() === 'user-agent')) {
    out['User-Agent'] = 'APlayer/9.0 (Linux; Android 16) ExoPlayer/1.0';
  }
  if (!Object.keys(out).some((k) => k.toLowerCase() === 'referer')) out.Referer = 'https://aliez.tv/';
  if (!Object.keys(out).some((k) => k.toLowerCase() === 'origin')) out.Origin = 'https://aliez.tv';
  if (!Object.keys(out).some((k) => k.toLowerCase() === 'cookie')) out.Cookie = 'passport=IG2GpFng03_23122025';
  return out;
}
function absUrl(base, ref) {
  try { return new URL(ref, base).toString(); } catch (_) { return ''; }
}
function rewriteManifest(text, requestUrl, rh) {
  const rhPart = rh ? '&rh=' + encodeURIComponent(rh) : '';
  const base = SW_PREFIX + '?u=';
  return String(text || '').split('\\n').map((line) => {
    const trim = line.trim();
    if (!trim || trim.startsWith('#')) {
      return line.replace(/URI="([^"]+)"/gi, (_, u) => {
        const abs = absUrl(requestUrl, u);
        return abs ? 'URI="' + base + encodeURIComponent(abs) + rhPart + '"' : _;
      });
    }
    const abs = absUrl(requestUrl, trim);
    if (!abs) return line;
    return base + encodeURIComponent(abs) + rhPart;
  }).join('\\n');
}
self.addEventListener('install', (e) => { self.skipWaiting(); });
self.addEventListener('activate', (e) => { e.waitUntil(self.clients.claim()); });
self.addEventListener('fetch', (event) => {
  const reqUrl = new URL(event.request.url);
  if (!reqUrl.pathname.endsWith('/a3sw') && reqUrl.pathname !== SW_PREFIX) return;
  event.respondWith((async () => {
    const target = reqUrl.searchParams.get('u') || '';
    const rhRaw = reqUrl.searchParams.get('rh') || '';
    if (!/^https?:\\/\\//i.test(target)) {
      return new Response('missing u', { status: 400 });
    }
    const headers = buildHeaders(decodeRh(rhRaw));
    let upstream;
    try {
      upstream = await fetch(target, { headers, redirect: 'follow', credentials: 'omit', mode: 'cors' });
    } catch (err) {
      // CORS may block opaque reads — retry no-cors is useless for HLS. Fall back to CF Worker.
      const worker = 'https://a3.phinemi.live/?u=' + encodeURIComponent(target) + (rhRaw ? '&rh=' + encodeURIComponent(rhRaw) : '');
      return Response.redirect(worker, 302);
    }
    const ct = (upstream.headers.get('content-type') || '').toLowerCase();
    const buf = await upstream.arrayBuffer();
    const peek = new TextDecoder().decode(buf.slice(0, Math.min(buf.byteLength, 64))).trimStart();
    const outHeaders = {
      'Content-Type': upstream.headers.get('content-type') || 'application/octet-stream',
      'Cache-Control': 'no-store',
      'Access-Control-Allow-Origin': '*'
    };
    if (peek.startsWith('#EXT') || ct.includes('mpegurl')) {
      const body = rewriteManifest(new TextDecoder().decode(buf), target, rhRaw);
      if (/<\\s*html|404 Not Found|CyberPanel/i.test(body)) {
        return new Response('A3 CDN blocked this network edge', { status: 502, headers: outHeaders });
      }
      outHeaders['Content-Type'] = 'application/vnd.apple.mpegurl';
      return new Response(body, { status: 200, headers: outHeaders });
    }
    if (!upstream.ok || /text\\/html/i.test(ct)) {
      const worker = 'https://a3.phinemi.live/?u=' + encodeURIComponent(target) + (rhRaw ? '&rh=' + encodeURIComponent(rhRaw) : '');
      return Response.redirect(worker, 302);
    }
    return new Response(buf, { status: upstream.status, headers: outHeaders });
  })());
});
`);
});

/** Fallback when SW is not controlling this client yet → CF Worker. */
router.get('/a3sw', (req, res) => {
  const target = String(req.query.u || req.query.url || '').trim();
  const rh = String(req.query.rh || '').trim();
  if (!/^https?:\/\//i.test(target)) return res.status(400).send('missing u');
  const worker = wrapA3CorsProxyUrl(target, { rh });
  res.setHeader('Cache-Control', 'no-store');
  return res.redirect(302, worker);
});

router.get('/api/channel-url/:slug', async (req, res) => {
  const accessCheck = validateChannelUrlApiAccess(req);
  if (!accessCheck.ok) {
    return res.status(403).json({ ok: false, error: accessCheck.reason || 'forbidden' });
  }
  const security = normalizeSecurityHardening(appConfig.security_hardening);
  if (security.enabled && security.api_rate_limit) {
    const ip = getForwardClientIp(req) || req.ip || 'unknown';
    const allowed = rateLimitAllow(channelUrlRateLimits, ip, CHANNEL_URL_API_RATE_LIMIT, 60 * 1000);
    if (!allowed) return res.status(429).json({ ok: false, error: 'Rate limit exceeded' });
  }
  const slug = req.params.slug;
  let channel = resolveChannelBySlug(slug);
  if (!channel && /^(alb_|albvod_)/i.test(slug)) channel = await resolveAlbChannelBySlugRuntime(req, slug, { verifyStream: false, tries: 1 });
  if (!channel) return res.status(404).json({ ok: false, error: 'Not found' });
  const channelAccessTier = resolveChannelAccessTierBySlug(slug);
  const viewerTier = resolveViewerChannelAccessTier(req);
  if (!isChannelAccessibleForViewer(channelAccessTier, viewerTier)) {
    return res.status(403).json({
      ok: false,
      error: 'channel_access_required',
      required_tier: channelAccessTier,
      viewer_tier: viewerTier
    });
  }
  const sourceKey = getChannelSourceKey(channel);
  const preferNoProxy = req.query.prefer_no_proxy === '1' || req.query.no_proxy === '1';
  const disableProxyForSource = preferNoProxy && (sourceKey === 'kool' || sourceKey === 'kool_lokke');
  if (!isSourceAccessibleNow(sourceKey)) return res.status(404).json({ ok: false, error: 'Source unavailable now' });
  const geoCheck = await validateSourceGeo(req, sourceKey);
  if (!geoCheck.ok) return res.status(451).json({ ok: false, error: 'Geo blocked', country: geoCheck.countryCode || '??' });
  if (sourceKey === 'alb' || sourceKey === 'alb_vod') {
    const verifiedAlb = await resolveAlbChannelBySlugRuntime(req, slug, { verifyStream: false, tries: 2 });
    if (!verifiedAlb) {
      return res.status(503).json({ ok: false, source_key: sourceKey, source_label: SOURCE_LABELS[sourceKey] || sourceKey, error: 'A3 channel unavailable right now' });
    }
    channel = verifiedAlb;
    const streamUrl = String(channel.url || '').trim();
    if (!/^https?:\/\//i.test(streamUrl)) {
      return res.status(503).json({
        ok: false,
        source_key: sourceKey,
        source_label: SOURCE_LABELS[sourceKey] || sourceKey,
        error: 'A3 channel unavailable right now'
      });
    }
    // Fresh URL. fastly → app direct (phone IP); Safari web can use direct_url (native HLS);
    // Chrome web cannot (CORS needs Worker, Worker IP is DC-blocked by fastlycache).
    const playOpts = buildA3PlaybackOptionsFromChannel(channel, req);
    const playUrl = buildA3PlaybackUrl(streamUrl, playOpts);
    const workerUrl = wrapA3CorsProxyUrl(streamUrl, playOpts);
    issuePlaybackCookieForSource(req, res, sourceKey, resolvePlayTokenTtlSec(sourceKey));
    const clientIpv4 = getLikelyClientIPv4(req);
    const a3Cdn = isAlbFastlyUrl(streamUrl) ? 'fastly' : 'other';
    const webBlocked = playOpts.webBlocked === true;
    res.setHeader('Cache-Control', 'no-store');
    return res.json({
      ok: true,
      source_key: sourceKey,
      source_label: SOURCE_LABELS[sourceKey] || sourceKey,
      mode: playOpts.preferDirect ? 'direct' : (playOpts.preferClientSw ? 'a3sw' : 'direct'),
      url: playUrl,
      proxy_url: workerUrl,
      direct_url: streamUrl,
      headers: playOpts.headers || {},
      user_agent: playOpts.userAgent || '',
      client_ipv4: clientIpv4 || '',
      expires_in: resolvePlayTokenTtlSec(sourceKey),
      overloaded: runtimePressureState.overloaded === true,
      a3_cdn: a3Cdn,
      a3_failover: channel._albFailoverTo || '',
      a3_web_blocked: webBlocked,
      error: webBlocked ? 'a3_fastly_web' : ''
    });
  }
  const playback = resolveWebPrimaryPlaybackPath(slug, req, channel, { disableProxyForSource });
  issuePlaybackCookieForSource(req, res, playback.sourceKey, resolvePlayTokenTtlSec(playback.sourceKey));
  const clientIpv4 = getLikelyClientIPv4(req);
  res.setHeader('Cache-Control', 'no-store');
  res.json({
    ok: true,
    source_key: playback.sourceKey,
    source_label: SOURCE_LABELS[playback.sourceKey] || playback.sourceKey,
    mode: playback.mode,
    url: appendClientIpQuery(playback.primaryUrl, clientIpv4),
    proxy_url: playback.proxyUrl ? appendClientIpQuery(playback.proxyUrl, clientIpv4) : '',
    client_ipv4: clientIpv4 || '',
    expires_in: resolvePlayTokenTtlSec(sourceKey),
    overloaded: runtimePressureState.overloaded === true
  });
});
router.get('/api/channel-preview/:slug', async (req, res) => {
  const flags = getFeatureFlags();
  if (!flags.channel_preview_hover) return res.status(404).json({ ok: false, error: 'Preview disabled' });
  const slug = createSlug(req.params.slug || '');
  if (!slug) return res.status(400).json({ ok: false, error: 'Invalid slug' });
  const channel = allCombined[slug];
  if (!channel) return res.status(404).json({ ok: false, error: 'Channel not found' });
  const cachedName = `${slug}.jpg`;
  const cachedPath = path.join(PREVIEW_DIR, cachedName);
  try {
    const stat = fs.statSync(cachedPath);
    if ((Date.now() - Number(stat.mtimeMs || 0)) <= 5 * 60 * 1000) {
      return res.json({ ok: true, url: `${BASE_PATH}/preview-cache/${encodeURIComponent(cachedName)}?t=${Math.floor(Number(stat.mtimeMs || 0))}` });
    }
  } catch {}
  const logo = normalizeHttpUrl(channel.logo || '');
  if (logo) return res.json({ ok: true, url: logo });
  return res.json({ ok: true, url: '' });
});
router.get('/api/epg/now-next/:slug', async (req, res) => {
  const slug = createSlug(req.params.slug || '');
  if (!slug) return res.status(400).json({ ok: false, error: 'Invalid slug' });
  const channel = allCombined[slug];
  if (!channel) return res.status(404).json({ ok: false, error: 'Channel not found' });
  const epgId = String(channel.epgId || channel.id || '').trim();
  const aliases = [
    channel.name,
    channel.slug,
    slug,
    channel.id,
    `${channel.name || ''}`.replace(/\s+/g, '.'),
    `${channel.name || ''}`.replace(/\s+/g, '-')
  ];
  const manualEpgSettings = normalizeManualEpgConfig(appConfig.manual_epg);
  const manualEpgUrl = getManualEpgUrlForSlug(slug);
  if (manualEpgSettings.enabled === true) {
    if (!manualEpgUrl) {
      return res.json({
        ok: true,
        has_epg: false,
        epg_id: '',
        now: null,
        next: null,
        now_ts: Date.now(),
        source: 'manual',
        reason: 'manual_epg_not_configured'
      });
    }
    const manualData = await fetchManualEpgNowNextByUrl(manualEpgUrl, aliases);
    const mapProgram = (item) => {
      if (!item || !item.start) return null;
      return {
        title: String(item.title || '').trim(),
        description: String(item.description || '').trim(),
        start: Number(item.start || 0),
        stop: Number(item.stop || 0)
      };
    };
    return res.json({
      ok: true,
      has_epg: !!(manualData.now || manualData.next),
      epg_id: '',
      now: mapProgram(manualData.now),
      next: mapProgram(manualData.next),
      now_ts: Date.now(),
      source: 'manual'
    });
  }
  if (!epgId && !aliases.filter(Boolean).length) return res.json({ ok: true, has_epg: false, reason: 'missing_epg_id' });
  let source = 'epgshare';
  let data = await awaitWithTimeout(fetchTvepgNowNextByChannelName(channel.name || ''), 5500);
  if (data && (data.now || data.next)) {
    source = 'tvepg';
    if (data.logo && (!String(channel.logo || '').trim() || String(channel.logo || '').includes('default'))) {
      channel.logo = data.logo;
    }
  } else {
    data = await fetchEpgNowNextForChannelId(epgId || slug, aliases);
    source = 'epgshare';
  }
  const mapProgram = (item) => {
    if (!item || !item.start) return null;
    return {
      title: String(item.title || '').trim(),
      description: String(item.description || '').trim(),
      start: Number(item.start || 0),
      stop: Number(item.stop || 0)
    };
  };
  return res.json({
    ok: true,
    has_epg: !!(data.now || data.next),
    epg_id: epgId,
    now: mapProgram(data.now),
    next: mapProgram(data.next),
    now_ts: Date.now(),
    source
  });
});
router.get('/preview-cache/:name', (req, res) => {
  const fileName = String(req.params.name || '').trim();
  if (!/^[a-z0-9_\-]+\.jpg$/i.test(fileName)) return res.status(404).send('Not found');
  const filePath = path.join(PREVIEW_DIR, fileName);
  if (!filePath.startsWith(PREVIEW_DIR)) return res.status(403).send('Forbidden');
  if (!fs.existsSync(filePath)) return res.status(404).send('Not found');
  res.setHeader('Cache-Control', 'public, max-age=120');
  res.sendFile(filePath);
});
router.get('/vod-assets/:name', (req, res) => {
  const fileName = path.basename(String(req.params.name || '').trim());
  if (!/^[a-z0-9_.\-]+$/i.test(fileName)) return res.status(404).send('Not found');
  const filePath = path.join(VOD_POSTERS_DIR, fileName);
  if (!filePath.startsWith(VOD_POSTERS_DIR)) return res.status(403).send('Forbidden');
  if (!fs.existsSync(filePath)) return res.status(404).send('Not found');
  res.setHeader('Cache-Control', 'public, max-age=86400');
  res.sendFile(filePath);
});

router.get('/api/stats', requireLoginOrToken, (req, res) => {
  const topChannels = Object.entries(channelViews)
    .sort((a,b) => b[1] - a[1])
    .slice(0, 20)
    .map(([slug, views]) => ({ slug, name: allCombined[slug]?.name || slug, views }));
  const sourceViewsMap = {};
  for (const [slug, viewsRaw] of Object.entries(channelViews || {})) {
    const channel = allCombined[slug];
    const sourceKey = channel ? getChannelSourceKey(channel) : 'unknown';
    const safeViews = Math.max(0, Number(viewsRaw || 0));
    sourceViewsMap[sourceKey] = (sourceViewsMap[sourceKey] || 0) + safeViews;
  }
  const topSources = Object.entries(sourceViewsMap)
    .map(([sourceKey, views]) => ({
      sourceKey,
      sourceLabel: SOURCE_LABELS[sourceKey] || sourceKey,
      views: Number(views || 0)
    }))
    .sort((a, b) => b.views - a.views)
    .slice(0, 12);
  const totalChannelViews = topSources.reduce((sum, row) => sum + Number(row.views || 0), 0);
  const traffic = buildTrafficAnalyticsSnapshot();
  const adSnippetStats = buildAdSnippetStatsSnapshot();
  res.json({
    totalViews: serverStats.totalViews,
    uniqueIps: (serverStats.uniqueIps || []).length,
    peakUsers: serverStats.peakUsers,
    activeNow: activeUsers.size,
    network: getServerNetworkSnapshot(),
    topChannels,
    customChannels: {
      tv: (customChannels.tv || []).length,
      sport: (customChannels.sport || []).length,
      nimi: (customChannels.nimi || []).length
    },
    customCategories: Object.keys(customCategories).length,
    sourceViews: {
      totalTrackedViews: totalChannelViews,
      topSources
    },
    vod: {
      totalItems: vodItems.length,
      publishedItems: vodItems.filter(item => item.status === 'published' && item.visibility === 'public').length,
      views: Number(serverStats.vod?.views || 0),
      watchTimeSec: Number(serverStats.vod?.watchTimeSec || 0),
      completions: Number(serverStats.vod?.completions || 0)
    },
    adSnippetStats,
    traffic,
    sourceHealth: normalizeSourceHealth(sourceHealth)
  });
});
router.get('/api/admin/playlists/:id/stats', requireLoginOrToken, async (req, res) => {
  const id = createSlug(String(req.params.id || ''));
  if (!id || !customPlaylists[id]) return res.status(404).json({ ok: false, error: 'Playlist not found' });
  const uaPolicy = resolvePlaylistUserAgentPolicy(customPlaylists[id]);
  const stats = await buildPlaylistAnalyticsSnapshotAsync(id);
  return res.json({
    ok: true,
    playlist: {
      id,
      name: String(customPlaylists[id].name || id),
      delivery_mode: normalizePlaylistDeliveryMode(customPlaylists[id].delivery_mode || customPlaylists[id].mode),
      user_agent_mode: uaPolicy.mode,
      user_agent_list_count: uaPolicy.list.length
    },
    stats
  });
});
router.get('/admin/stats/ad-snippets.csv', requireLogin, (req, res) => {
  const group = String(req.query.group || 'day').trim().toLowerCase();
  const groupBy = ['day', 'country', 'ip', 'kind'].includes(group) ? group : 'day';
  const days = Math.max(1, Math.min(60, parseInt(req.query.days, 10) || 7));
  const limit = Math.max(1, Math.min(50000, parseInt(req.query.limit, 10) || 5000));
  const csv = buildAdSnippetStatsCsv({ groupBy, days, limit });
  res.setHeader('Content-Type', 'text/csv; charset=utf-8');
  res.setHeader('Content-Disposition', `attachment; filename="ad-snippets-${groupBy}-${days}d.csv"`);
  res.send(csv);
});

router.post('/telegram/webhook/:secret', async (req, res) => {
  const alerts = normalizeAlertsSettings(appConfig.alerts);
  if (!alerts.enabled || !alerts.telegram_enabled || !alerts.telegram_bot_token) {
    return res.status(404).json({ ok: false, error: 'Telegram control disabled' });
  }
  const secret = String(req.params.secret || '').trim();
  if (!alerts.telegram_webhook_secret || secret !== alerts.telegram_webhook_secret) {
    return res.status(403).json({ ok: false, error: 'Forbidden' });
  }
  const msg = req.body?.message || req.body?.edited_message;
  if (!msg || typeof msg !== 'object') return res.json({ ok: true });
  const incomingChatId = String(msg?.chat?.id || '').trim();
  const allowedChatId = String(alerts.telegram_chat_id || '').trim();
  if (allowedChatId && incomingChatId && incomingChatId !== allowedChatId) {
    return res.json({ ok: true });
  }
  const text = String(msg?.text || '').trim();
  if (!text.startsWith('/')) return res.json({ ok: true });
  const [rawCommand, ...restArgs] = text.split(/\s+/).filter(Boolean);
  const command = String(rawCommand || '').toLowerCase();
  const reply = async (message) => {
    if (!incomingChatId) return;
    await sendTelegramMessage(incomingChatId, message);
  };
  const sourceHealthSnapshot = normalizeSourceHealth(sourceHealth);
  const deletedSources = SOURCE_KEYS.filter(key => isSourceDeleted(key));
  const scheduledOffSources = SOURCE_KEYS.filter(key => !isSourceScheduleActive(key));
  try {
    if (command === '/start' || command === '/help') {
      await reply(
        'Telegram Control Commands:\\n'
        + '/status - info i plote i serverit\\n'
        + '/health - health score per source\\n'
        + '/refresh - refresh kanalet\\n'
        + '/delete_source <key> - fshi source\\n'
        + '/restore_sources - rikthe source-et\\n'
        + '/sources - lista e source-ve\\n'
        + '/users - users aktiv me detaje\\n'
        + '/audit - 10 eventet e fundit'
      );
      return res.json({ ok: true });
    }
    if (command === '/status') {
      const sourceCounts = buildSourceCountsFromCombined(allCombined);
      if (isSourceAccessibleNow('alb')) sourceCounts.alb = Number(sourceHealthSnapshot?.alb?.channelCount || 0);
      const lines = SOURCE_KEYS.map(key => `${SOURCE_LABELS[key] || key}: ${sourceCounts[key] || 0}`).join('\\n');
      await reply(
        `STATUS\\nActive users: ${activeUsers.size}\\nTotal channels: ${Object.keys(allCombined).length}\\n`
        + `Deleted sources: ${deletedSources.join(', ') || 'none'}\\n`
        + `Scheduled OFF now: ${scheduledOffSources.join(', ') || 'none'}\\n\\nSource counts:\\n${lines}`
      );
      return res.json({ ok: true });
    }
    if (command === '/health') {
      const lines = SOURCE_KEYS.map(key => {
        const item = sourceHealthSnapshot[key] || {};
        const score = Number(item.score || 0);
        const r200 = Math.round(Number(item.ratio200 || 0) * 100);
        const r404 = Math.round(Number(item.ratio404 || 0) * 100);
        const count = Number(item.channelCount || 0);
        return `${SOURCE_LABELS[key] || key}: ch=${count} score=${score}% 200=${r200}% 404=${r404}%`;
      }).join('\\n');
      await reply(`SOURCE HEALTH\\n${lines}`);
      return res.json({ ok: true });
    }
    if (command === '/sources') {
      const lines = SOURCE_KEYS.map(key => {
        const deleted = isSourceDeleted(key) ? 'deleted' : 'active';
        const sched = isSourceScheduleActive(key) ? 'in-window' : 'off-window';
        return `${key}: ${deleted}, ${sched}`;
      }).join('\\n');
      await reply(`SOURCES\\n${lines}`);
      return res.json({ ok: true });
    }
    if (command === '/refresh') {
      await reply('Refresh u nis...');
      appendAuditLog('telegram_refresh_channels', null, {}, `telegram:${incomingChatId || 'unknown'}`);
      updateDatabases({ forceProdApiFetch: true })
        .then(() => sendTelegramMessage(incomingChatId, 'Refresh u krye me sukses.'))
        .catch((error) => sendTelegramMessage(incomingChatId, `Refresh dështoi: ${String(error?.message || 'unknown error')}`));
      return res.json({ ok: true });
    }
    if (command === '/delete_source') {
      const sourceKey = String(restArgs[0] || '').trim();
      if (!SOURCE_KEYS.includes(sourceKey)) {
        await reply(`Source i pavlefshëm. Përdor një nga: ${SOURCE_KEYS.join(', ')}`);
        return res.json({ ok: true });
      }
      createSourceDeleteSnapshot(null, [sourceKey]);
      const deleted = normalizeDeletedSources(appConfig.deleted_sources);
      deleted[sourceKey] = true;
      appConfig.deleted_sources = deleted;
      saveJSON(CONFIG_FILE, appConfig);
      appendAuditLog('telegram_delete_source', null, { sourceKey }, `telegram:${incomingChatId || 'unknown'}`);
      await updateDatabases();
      await reply(`Source ${sourceKey} u fshi me sukses.`);
      return res.json({ ok: true });
    }
    if (command === '/restore_sources') {
      appConfig.deleted_sources = normalizeDeletedSources({});
      saveJSON(CONFIG_FILE, appConfig);
      appendAuditLog('telegram_restore_sources', null, { restored_all: true }, `telegram:${incomingChatId || 'unknown'}`);
      await updateDatabases();
      await reply('Të gjitha source-et u rikthyen.');
      return res.json({ ok: true });
    }
    if (command === '/audit') {
      const rows = auditLog.slice(0, 10).map(entry => {
        const dt = new Date(Number(entry.ts || Date.now())).toISOString().replace('T', ' ').slice(0, 19);
        return `${dt} | ${entry.action} | ${entry.actor}`;
      }).join('\\n');
      await reply(`AUDIT (last 10)\\n${rows || 'No entries'}`);
      return res.json({ ok: true });
    }
    if (command === '/users') {
      const now = Date.now();
      const rows = Array.from(activeUsers.values()).slice(0, 20).map(user => {
        const ip = user.ipv4 || user.ipv6 || user.ip || '-';
        const device = [user.device || '-', user.deviceModel || '', user.browser || ''].filter(Boolean).join(' | ');
        const ch = user.channel_name || 'Kryefaqe';
        const pingAgo = Math.max(0, Math.round((now - Number(user.last_ping || now)) / 1000));
        const fp = String(user.fingerprintHash || '-').slice(0, 18);
        const ck = String(user.fingerprintCookieId || '-').slice(0, 18);
        return `${ip} | ${device} | ${ch} | FP ${fp} | CK ${ck} | ping ${pingAgo}s`;
      }).join('\\n');
      await reply(`ACTIVE USERS (${activeUsers.size})\\n${rows || 'none'}`);
      return res.json({ ok: true });
    }
    await reply('Komandë e panjohur. Përdor /help');
    return res.json({ ok: true });
  } catch (error) {
    await reply(`Gabim: ${String(error?.message || 'unknown error')}`);
    return res.json({ ok: false });
  }
});

