function buildPublicVerificationMetaHeadHtml() {
  const siteOwnership = normalizeSiteOwnershipConfig(appConfig.site_ownership);
  const raw = String(buildSiteOwnershipMetaTagsText(siteOwnership) || '').trim();
  if (!raw) return '';
  return renderVerificationMetaTagsHtml(raw);
}
function buildPublicAnalyticsHeadHtml() {
  const siteOwnership = normalizeSiteOwnershipConfig(appConfig.site_ownership);
  const gaId = normalizeGoogleAnalyticsMeasurementId(siteOwnership.ga_measurement_id || '');
  if (!gaId) return '';
  return `<script async src="https://www.googletagmanager.com/gtag/js?id=${escapeHtmlAttr(gaId)}"></script>\n<script>\nwindow.dataLayer = window.dataLayer || [];\nfunction gtag(){dataLayer.push(arguments);}\ngtag('js', new Date());\ngtag('config', ${JSON.stringify(gaId)}, { anonymize_ip: true, send_page_view: true });\n</script>`;
}
function buildPublicEzoicHeadHtml() {
  const adSnippets = normalizeAdSnippetConfig(appConfig.ad_snippets);
  if (adSnippets.ezoic_enabled === false) return '';
  return [
    '<script async src="//www.ezojs.com/ezoic/sa.min.js"></script>',
    '<script>',
    'window.ezstandalone = window.ezstandalone || {};',
    'ezstandalone.cmd = ezstandalone.cmd || [];',
    '</script>',
    '<script async src="https://cmp.gatekeeperconsent.com/min.js" data-cfasync="false"></script>',
    '<script async src="https://the.gatekeeperconsent.com/cmp.min.js" data-cfasync="false"></script>',
    '<script async src="//www.ezojs.com/ezoic/analytics.js"></script>'
  ].join('\n');
}
function combinePublicExtraHead(extra = '') {
  return [
    buildPublicVerificationMetaHeadHtml(),
    buildPublicAnalyticsHeadHtml(),
    buildPublicEzoicHeadHtml(),
    String(extra || '').trim()
  ].filter(Boolean).join('\n');
}


function persistVodState() {
  saveJSON(VOD_ITEMS_FILE, vodItems);
  saveJSON(VOD_CATEGORIES_FILE, vodCategories);
  saveJSON(VOD_COLLECTIONS_FILE, vodCollections);
  saveJSON(STATS_FILE, serverStats);
}
function issueVodStreamToken(vodId = '', req = null, ttlSec = 2 * 60 * 60) {
  const safeId = sanitizeText(vodId, 120);
  if (!safeId) return '';
  const options = { ttlSec };
  if (req) {
    const ip = getLikelyClientIp(req);
    if (ip) options.bindIp = ip;
    options.bindUaHash = hashUserAgent(req.headers?.['user-agent'] || '');
  }
  return issuePlayToken(`vod:${safeId}`, ttlSec, options);
}
function resolveVodByToken(token = '', req = null) {
  const data = verifyPlayToken(String(token || ''));
  if (!data) return null;
  if (!String(data.slug || '').startsWith('vod:')) return null;
  if (data.bindIp && req && String(getLikelyClientIp(req) || '') !== String(data.bindIp || '')) return null;
  if (data.bindUaHash && req) {
    const uaHash = hashUserAgent(req.headers?.['user-agent'] || '');
    if (uaHash !== data.bindUaHash) return null;
  }
  const vodId = sanitizeText(String(data.slug || '').slice(4), 120);
  if (!vodId) return null;
  return findVodItemById(vodId);
}
function findVodItemBySlug(slug = '') {
  const safe = createSlug(slug || '');
  return vodItems.find(item => createSlug(item.slug || '') === safe);
}
function findVodItemById(id = '') {
  const safe = sanitizeText(id, 140);
  return vodItems.find(item => String(item.id || '') === safe);
}
function parseVodBulkPayload(payload = '') {
  const text = String(payload || '').trim();
  if (!text) return [];
  try {
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed)) return parsed;
    if (parsed && typeof parsed === 'object' && Array.isArray(parsed.items)) return parsed.items;
  } catch {}
  const lines = text.split(/\r?\n/g);
  const items = [];
  let pendingTitle = '';
  for (const lineRaw of lines) {
    const line = String(lineRaw || '').trim();
    if (!line) continue;
    if (line.startsWith('#EXTINF')) {
      const title = line.split(',').slice(1).join(',').trim();
      pendingTitle = title || '';
      continue;
    }
    if (/^https?:\/\//i.test(line)) {
      items.push({ title: pendingTitle || `Imported ${items.length + 1}`, source_url: line, visibility: 'private', status: 'draft' });
      pendingTitle = '';
    }
  }
  return items;
}
function buildVodListSnapshot(query = {}) {
  const genreFilter = createSlug(query.genre || '');
  const yearFilter = String(query.year || '').trim();
  const q = String(query.query || '').trim().toLowerCase();
  const status = String(query.status || '').trim().toLowerCase();
  const visibility = String(query.visibility || '').trim().toLowerCase();
  const includePrivate = query.includePrivate === true;
  const sort = String(query.sort || 'newest').trim().toLowerCase();
  let filtered = vodItems.filter(item => {
    if (!item || typeof item !== 'object') return false;
    if (!includePrivate && (item.status !== 'published' || item.visibility !== 'public')) return false;
    if (status && String(item.status || '').toLowerCase() !== status) return false;
    if (visibility && String(item.visibility || '').toLowerCase() !== visibility) return false;
    if (yearFilter && String(item.year || '') !== yearFilter) return false;
    if (genreFilter) {
      const genres = Array.isArray(item.genre) ? item.genre : [];
      const ok = genres.some(g => createSlug(g) === genreFilter);
      if (!ok) return false;
    }
    if (q) {
      const hay = `${item.title || ''} ${(item.genre || []).join(' ')} ${item.language || ''}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });
  if (sort === 'year_desc') filtered.sort((a, b) => Number(b.year || 0) - Number(a.year || 0));
  else if (sort === 'title_asc') filtered.sort((a, b) => String(a.title || '').localeCompare(String(b.title || '')));
  else filtered.sort((a, b) => new Date(b.updated_at || 0).getTime() - new Date(a.updated_at || 0).getTime());
  return filtered;
}
function buildVodSeriesSnapshot(options = {}) {
  const includePrivate = options.includePrivate === true;
  const source = vodItems.filter(item => {
    if (!includePrivate && (item.status !== 'published' || item.visibility !== 'public')) return false;
    return true;
  });
  const movieItems = [];
  const seriesMap = new Map();
  for (const item of source) {
    const isEpisode = String(item.type || '').toLowerCase() === 'series_episode' || !!String(item.series_id || '').trim();
    if (!isEpisode) {
      movieItems.push(item);
      continue;
    }
    const rawSeriesId = String(item.series_id || item.title || item.slug || item.id || '').trim();
    const seriesId = buildVodSlug(rawSeriesId || item.id);
    if (!seriesMap.has(seriesId)) {
      seriesMap.set(seriesId, {
        series_id: seriesId,
        title: sanitizeText(item.series_title || item.title || seriesId, 220),
        poster: item.poster || '',
        logo_url: item.logo_url || '',
        backdrop: item.backdrop || '',
        language: item.language || '',
        genre: Array.isArray(item.genre) ? item.genre : [],
        status: item.status || 'draft',
        visibility: item.visibility || 'private',
        episodes: []
      });
    }
    const row = seriesMap.get(seriesId);
    row.episodes.push(item);
    if (!row.poster && item.poster) row.poster = item.poster;
    if (!row.logo_url && item.logo_url) row.logo_url = item.logo_url;
    if (!row.backdrop && item.backdrop) row.backdrop = item.backdrop;
  }
  for (const row of seriesMap.values()) {
    const seriesMeta = vodCollections?.[row.series_id];
    if (seriesMeta && typeof seriesMeta === 'object') {
      if (seriesMeta.title) row.title = sanitizeText(seriesMeta.title, 220);
      if (seriesMeta.poster) row.poster = normalizeHttpUrl(seriesMeta.poster);
      if (seriesMeta.logo_url) row.logo_url = normalizeHttpUrl(seriesMeta.logo_url);
      if (seriesMeta.visibility) row.visibility = normalizeVodVisibility(seriesMeta.visibility);
    }
    row.episodes.sort((a, b) => {
      const sa = Number(a.season || 0);
      const sb = Number(b.season || 0);
      if (sa !== sb) return sa - sb;
      return Number(a.episode_number || 0) - Number(b.episode_number || 0);
    });
  }
  return {
    movies: movieItems,
    series: Array.from(seriesMap.values()).sort((a, b) => String(a.title || '').localeCompare(String(b.title || '')))
  };
}
function buildVodWatermarkPayload(req) {
  const cfg = normalizeDynamicWatermarkConfig(appConfig.dynamic_watermark);
  const sid = String(req.sessionID || '').slice(-8);
  const ip = String(getLikelyClientIp(req) || '').trim();
  const ipSuffix = ip ? ip.split('.').slice(-2).join('.') : '';
  const text = `VOD ${sid || 'guest'}${cfg.show_ip_suffix && ipSuffix ? ` • ${ipSuffix}` : ''}`;
  return {
    watermark_enabled: cfg.vod_enabled === true,
    watermark_text: text,
    watermark_position: cfg.position || 'bottom-right',
    watermark_opacity: Number(cfg.opacity || 0.28),
    watermark_update_sec: Number(cfg.update_sec || 8)
  };
}

router.get('/api/vod/list', (req, res) => {
  const includePrivate = !!(req.session?.loggedIn || (String(req.headers['x-admin-token'] || '') === ADMIN_TOKEN));
  const page = Math.max(1, parseInt(req.query.page, 10) || 1);
  const pageSize = Math.max(1, Math.min(80, parseInt(req.query.page_size, 10) || 24));
  const all = buildVodListSnapshot({ ...req.query, includePrivate });
  const start = (page - 1) * pageSize;
  const items = all.slice(start, start + pageSize);
  res.json({ ok: true, total: all.length, page, page_size: pageSize, items });
});

function getVodSessionKey(req, vodId = '') {
  const id = sanitizeText(vodId || '', 120);
  const sid = String(req.sessionID || '').trim();
  const ip = String(getLikelyClientIp(req) || '').trim();
  const uaHash = hashUserAgent(req.headers?.['user-agent'] || '').slice(0, 12);
  return `${id}|${sid || ip || 'guest'}|${uaHash || 'ua'}`;
}
function pruneVodSessionMaps() {
  const now = Date.now();
  const maxAgeMs = 12 * 60 * 60 * 1000;
  for (const [key, value] of vodProgressSessionState.entries()) {
    if ((now - Number(value?.updatedAt || 0)) > maxAgeMs) vodProgressSessionState.delete(key);
  }
  for (const [key, value] of vodCompletionSessionState.entries()) {
    if ((now - Number(value || 0)) > maxAgeMs) vodCompletionSessionState.delete(key);
  }
}

router.post('/api/vod/analytics/view', express.json({ limit: '30kb' }), (req, res) => {
  const id = sanitizeText(req.body?.id || '', 120);
  const item = findVodItemById(id);
  if (!item) return res.status(404).json({ ok: false, error: 'VOD not found' });
  item.analytics.views = Math.max(0, Number(item.analytics.views || 0) + 1);
  item.analytics.updatedAt = Date.now();
  serverStats.vod.views = Math.max(0, Number(serverStats.vod.views || 0) + 1);
  persistVodState();
  res.json({ ok: true, analytics: item.analytics });
});

router.post('/api/vod/analytics/progress', express.json({ limit: '40kb' }), (req, res) => {
  const id = sanitizeText(req.body?.id || '', 120);
  const watchTimeSec = Math.max(0, Math.min(24 * 60 * 60, Number(req.body?.watch_time_sec || 0)));
  const completed = req.body?.completed === true || String(req.body?.completed || '').toLowerCase() === 'true';
  const item = findVodItemById(id);
  if (!item) return res.status(404).json({ ok: false, error: 'VOD not found' });
  pruneVodSessionMaps();
  const sessionKey = getVodSessionKey(req, id);
  const prev = vodProgressSessionState.get(sessionKey) || { watchTimeSec: 0, updatedAt: 0 };
  const previousWatch = Math.max(0, Number(prev.watchTimeSec || 0));
  const deltaWatch = watchTimeSec > previousWatch ? Math.min(watchTimeSec - previousWatch, 3600) : 0;
  if (deltaWatch > 0) {
    item.analytics.watchTimeSec = Math.max(0, Number(item.analytics.watchTimeSec || 0) + deltaWatch);
    serverStats.vod.watchTimeSec = Math.max(0, Number(serverStats.vod.watchTimeSec || 0) + deltaWatch);
  }
  vodProgressSessionState.set(sessionKey, {
    watchTimeSec: Math.max(previousWatch, watchTimeSec),
    updatedAt: Date.now()
  });
  if (completed) {
    const lastCompletion = Number(vodCompletionSessionState.get(sessionKey) || 0);
    if (!lastCompletion || (Date.now() - lastCompletion) > (30 * 60 * 1000)) {
      item.analytics.completions = Math.max(0, Number(item.analytics.completions || 0) + 1);
      serverStats.vod.completions = Math.max(0, Number(serverStats.vod.completions || 0) + 1);
      vodCompletionSessionState.set(sessionKey, Date.now());
    }
  }
  const views = Math.max(1, Number(item.analytics.views || 0));
  item.analytics.completionRate = Math.max(0, Math.min(100, (Number(item.analytics.completions || 0) / views) * 100));
  item.analytics.updatedAt = Date.now();
  persistVodState();
  res.json({ ok: true, analytics: item.analytics });
});

