// ─── MAIN PAGE ────────────────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════
function detectDeviceProfile(req) {
  const ua = String(req.headers['user-agent'] || '').toLowerCase();
  const secPlatform = String(req.headers['sec-ch-ua-platform'] || '').toLowerCase();
  const isAndroid = ua.includes('android') || secPlatform.includes('android');
  const isIOS = /iphone|ipad|ipod/.test(ua) || secPlatform.includes('ios');
  const isDesktop = !isAndroid && !isIOS;
  const cfg = normalizeDeviceAccessConfig(appConfig.device_access);
  const webviewHints = String(cfg.android_webview_ua_keywords || '').toLowerCase().split(/[;,\n]+/).map(v => v.trim()).filter(Boolean);
  const isAndroidWebView = isAndroid && webviewHints.some(hint => ua.includes(hint));
  return { isAndroid, isIOS, isDesktop, isAndroidWebView };
}
function filterChannelsForDevice(sourceMap, req) {
  const cfg = normalizeDeviceAccessConfig(appConfig.device_access);
  if (!cfg.enabled || !cfg.android_limited_mode) return sourceMap;
  const profile = detectDeviceProfile(req);
  if (!profile.isAndroid) return sourceMap;
  if (cfg.allow_android_full_for_webview && profile.isAndroidWebView) return sourceMap;
  const allowed = new Set(cfg.android_preview_slugs || []);
  return Object.fromEntries(Object.entries(sourceMap || {}).filter(([slug]) => allowed.has(slug)));
}
function getAndroidAccessNotice(req) {
  const cfg = normalizeDeviceAccessConfig(appConfig.device_access);
  if (!cfg.enabled || !cfg.android_limited_mode) return '';
  const profile = detectDeviceProfile(req);
  if (!profile.isAndroid) return '';
  if (cfg.allow_android_full_for_webview && profile.isAndroidWebView) return '';
  const text = String(cfg.android_notice_text || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const cta = cfg.android_playstore_url ? ` <a href="${cfg.android_playstore_url}" target="_blank" rel="noopener" style="color:#fff;text-decoration:underline;font-weight:700">Play Store</a>` : '';
  return `<div style="background:linear-gradient(90deg,#ff6a00,#ee0979);color:#fff;padding:10px 12px;border-radius:10px;margin:0 0 12px 0;font-size:.82rem"><i class="fas fa-mobile-alt"></i> ${text}${cta}</div>`;
}

router.get('/', (req, res) => {
  const clientIp = getLikelyClientIp(req);
  if (clientIp) {
    const userAgent = req.headers['user-agent'] || '';
    koolService.primeClientSignature({
      clientIp,
      userAgent
    }).catch(() => {});
    koolLokkeService.primeClientSignature({
      clientIp,
      userAgent
    }).catch(() => {});
  }
  const vis = filterChannelsForDevice(visibleChannels(allCombined), req);
  const featuredSlugs = Array.isArray(appConfig.featured_channels)
    ? appConfig.featured_channels.filter(slug => !!vis[slug])
    : [];
  const manualMainEntries = featuredSlugs.map(slug => [slug, vis[slug]]).filter(([, ch]) => !!ch);
  const limited = (manualMainEntries.length ? manualMainEntries : Object.entries(vis)).slice(0, appConfig.main_page_limit);
  const manualMainEnabled = manualMainEntries.length > 0;
  const cards = buildCards(Object.fromEntries(limited), { redirectKoolOnMain: false, pageType: 'main' });
  const urlMap = buildPlayerUrlMap(allCombined, req, { forceDirectSources: ['kool', 'kool_lokke'] });
  const customCategoryEntries = Object.entries(customCategories).sort((a, b) => (Number(a[1].order || 0) - Number(b[1].order || 0)) || String(a[1].name || '').localeCompare(String(b[1].name || '')));
  const visibleCustomCategoryEntries = customCategoryEntries.filter(([, cat]) => cat?.showOnMain !== false);
  const customCards = buildCustomCategoryCardsHtml() || `<div class="cat-card" style="grid-column:1/-1;cursor:default">
<div class="cat-icon"><i class="fas fa-folder-open"></i></div>
<div class="cat-info"><h3>Nuk ka kategori custom aktive</h3><p>Shto kategori nga Admin → Kategori.</p></div>
<div class="cat-count">0</div></div>`;
  const navHtml = NAV_PUBLIC.replace('class="nav-link nav-link-cta" data-testid="public-nav-live-tv-link"', 'class="nav-link nav-link-cta active" data-testid="public-nav-live-tv-link"');
  const pageContentHtml = renderMainPageContent({
    basePath: BASE_PATH,
    customCards: `${getAndroidAccessNotice(req)}${customCards}`,
    visibleMainCount: limited.length,
    manualMainEnabled,
    cards
  });
  const playerScriptHtml = playerScript(urlMap, appConfig.player_defaults, appConfig.player_source_defaults, {
    redirectKoolOnMain: false,
    pageType: 'main'
  });
  res.send(renderPublicLayout({
    baseStyle: BASE_STYLE,
    title: 'TV Server',
    extraHeadHtml: combinePublicExtraHead(),
    navPublicHtml: navHtml,
    playerModalHtml: PLAYER_MODAL,
    pageContentHtml,
    playerScriptHtml
  }));
});

function renderWatchPageForSlug(req, res, slug) {
  const vis = filterChannelsForDevice(visibleChannels(allCombined), req);
  const channel = vis[slug];
  if (!channel) return res.status(404).send('Kanali nuk u gjet ose nuk është publik.');
  const featuredSlugs = Array.isArray(appConfig.featured_channels)
    ? appConfig.featured_channels.filter(item => !!vis[item])
    : [];
  const manualMainEntries = featuredSlugs.map(item => [item, vis[item]]).filter(([, ch]) => !!ch);
  const limited = (manualMainEntries.length ? manualMainEntries : Object.entries(vis)).slice(0, appConfig.main_page_limit);
  const manualMainEnabled = manualMainEntries.length > 0;
  const cards = buildCards(Object.fromEntries(limited), { redirectKoolOnMain: false, pageType: 'main' });
  const urlMap = buildPlayerUrlMap(allCombined, req, { forceDirectSources: ['kool', 'kool_lokke'] });
  const customCards = buildCustomCategoryCardsHtml();
  const pageContentHtml = renderMainPageContent({
    basePath: BASE_PATH,
    customCards,
    visibleMainCount: limited.length,
    manualMainEnabled,
    cards
  });
  const playerScriptHtml = playerScript(urlMap, appConfig.player_defaults, appConfig.player_source_defaults, {
    redirectKoolOnMain: false,
    pageType: 'watch',
    autoOpenSlug: slug
  });
  const channelName = String(channel.name || slug).replace(/"/g, '&quot;');
  const channelLogo = String(channel.logo || '').trim();
  const watchUrl = `${getPublicBaseUrl(req)}${BASE_PATH}/watch-open/${encodeURIComponent(slug)}`;
  const extraHeadHtml = [
    `<meta property="og:title" content="${channelName}">`,
    `<meta property="og:description" content="Duke transmetuar live tani">`,
    `<meta property="og:type" content="website">`,
    `<meta property="og:url" content="${watchUrl.replace(/"/g, '&quot;')}">`,
    channelLogo ? `<meta property="og:image" content="${channelLogo.replace(/"/g, '&quot;')}">` : ''
  ].join('');
  res.send(renderPublicLayout({
    baseStyle: BASE_STYLE,
    title: `${channel.name} - Live`,
    extraHeadHtml: combinePublicExtraHead(extraHeadHtml),
    navPublicHtml: NAV_PUBLIC,
    playerModalHtml: PLAYER_MODAL,
    pageContentHtml,
    playerScriptHtml
  }));
}
router.get('/api/watch-link/:slug', (req, res) => {
  const slug = createSlug(req.params.slug || '');
  const vis = filterChannelsForDevice(visibleChannels(allCombined), req);
  if (!slug || !vis[slug]) return res.status(404).json({ ok: false, error: 'Channel not found' });
  const channelTier = resolveChannelAccessTierBySlug(slug);
  const viewerTier = resolveViewerChannelAccessTier(req);
  if (!isChannelAccessibleForViewer(channelTier, viewerTier)) {
    return res.status(403).json({ ok: false, error: 'channel_access_required', required_tier: channelTier, viewer_tier: viewerTier });
  }
  const token = issueWatchPageToken(slug, req, 180);
  if (!token) return res.status(500).json({ ok: false, error: 'Failed to issue token' });
  return res.json({ ok: true, url: `${BASE_PATH}/watch/${encodeURIComponent(token)}`, expires_in: 180 });
});
router.get('/watch-open/:slug', (req, res) => {
  const slug = createSlug(req.params.slug || '');
  const vis = filterChannelsForDevice(visibleChannels(allCombined), req);
  if (!slug || !vis[slug]) return res.status(404).send('Kanali nuk u gjet!');
  const channelTier = resolveChannelAccessTierBySlug(slug);
  const viewerTier = resolveViewerChannelAccessTier(req);
  if (!isChannelAccessibleForViewer(channelTier, viewerTier)) {
    const message = channelTier === 'normal'
      ? 'Ky kanal është vetëm për paketën Normal.'
      : 'Ky kanal është vetëm për paketën Premium.';
    return res.status(403).send(message);
  }
  const token = issueWatchPageToken(slug, req, 180);
  if (!token) return res.status(500).send('Nuk u krijua link i përkohshëm.');
  return res.redirect(`${BASE_PATH}/watch/${encodeURIComponent(token)}`);
});
router.get('/watch/:token', (req, res) => {
  const tokenData = verifyPlayToken(String(req.params.token || ''));
  if (!tokenData) return res.status(404).send('Ky link ka skaduar ose është i pavlefshëm.');
  if (tokenData.bindIp) {
    const ip = getLikelyClientIp(req);
    if (String(ip || '') !== String(tokenData.bindIp || '')) return res.status(403).send('Ky link është i lidhur me një klient tjetër.');
  }
  if (tokenData.bindUaHash) {
    const uaHash = hashUserAgent(req.headers?.['user-agent'] || '');
    if (uaHash !== tokenData.bindUaHash) return res.status(403).send('Ky link është i lidhur me një browser tjetër.');
  }
  if (!consumeWatchPageNonce(tokenData, req)) return res.status(410).send('Ky link është përdorur ose ka skaduar.');
  return renderWatchPageForSlug(req, res, createSlug(tokenData.slug || ''));
});
