router.get('/playlist/:id.m3u', (req, res) => {
  const { id } = req.params;
  const base = getRelayBaseUrl(req);
  if (customPlaylists[id]) {
    const pl  = customPlaylists[id];
    const deliveryMode = normalizePlaylistDeliveryMode(pl.delivery_mode || pl.mode);
    const endpointMode = resolvePlaylistEndpointMode(pl);
    const uaPolicy = enforcePlaylistUserAgentPolicy(req, pl, id, `${id}.m3u`);
    if (!uaPolicy.ok) return res.status(403).send('User-Agent nuk lejohet për këtë playlist.');
    const chs = Object.fromEntries((pl.channels || []).filter(s => allCombined[s]).map(s => [s, allCombined[s]]));
    const vods = (pl.vod_items || []).map(vodId => findVodItemById(vodId)).filter(item => !!item);
    res.setHeader('Content-Type', 'audio/x-mpegurl');
    res.setHeader('Content-Disposition', `attachment; filename="${id}.m3u"`);
    const reqMeta = getPlaylistRequestMeta(req);
    recordPlaylistAnalyticsEvent(id, {
      type: 'download',
      mode: deliveryMode,
      ...reqMeta
    });
    return res.send(makePrivatePlaylistM3U(id, chs, pl.name, base, vods, {
      deliveryMode,
      endpointMode,
      channelOrder: (pl.channels || []).filter(s => allCombined[s]),
      playlist: pl
    }));
  }
  return res.status(403).send('Lejohen vetëm playlist private.');
});
router.get('/playlist/:id/:slug.m3u8', async (req, res) => {
  const id = String(req.params.id || '').trim();
  const slugRaw = String(req.params.slug || '').trim();
  const pl = customPlaylists[id];
  if (!pl) return res.status(404).send('Playlist not found');
  const deliveryMode = normalizePlaylistDeliveryMode(pl.delivery_mode || pl.mode);
  const meta = getPlaylistRequestMeta(req, { mode: deliveryMode });
  const uaPolicy = enforcePlaylistUserAgentPolicy(req, pl, id, slugRaw);
  if (!uaPolicy.ok) return res.status(403).send('User-Agent nuk lejohet për këtë playlist.');
  const resolvedSlug = resolvePlaylistAllowedChannelSlug(pl, slugRaw);
  if (!resolvedSlug) return res.status(404).send('Channel not in playlist');
  const slug = resolvedSlug;
  let channel = allCombined[slug];
  if (!channel) return res.status(404).send('Channel not found');
  const sourceKey = getChannelSourceKey(channel);
  if (!isSourceAccessibleNow(sourceKey)) return res.status(404).send('Not Found');
  const geoCheck = await validateSourceGeo(req, sourceKey);
  if (!geoCheck.ok) return res.status(451).send('Geo blocked');
  if (sourceKey === 'alb' || sourceKey === 'alb_vod') {
    const verifiedAlb = await resolveAlbChannelBySlugRuntime(req, slug, { verifyStream: false, tries: 2 });
    if (!verifiedAlb) return res.status(503).send('A3 channel unavailable right now');
    channel = verifiedAlb;
  }
  recordPlaylistAnalyticsEvent(id, {
    type: 'channel_click',
    target: slug,
    mode: deliveryMode,
    ...meta
  });
  const sourceKeyForCookie = getChannelSourceKey(channel);
  issuePlaybackCookieForSource(req, res, sourceKeyForCookie, resolvePlayTokenTtlSec(sourceKeyForCookie));
  req.playlistDelivery = { id, slug, mode: deliveryMode };
  return deliverChannelManifest(req, res, slug, channel);
});
router.get('/playlist/:id/vod/:vodId.m3u8', (req, res) => {
  const id = String(req.params.id || '').trim();
  const vodId = sanitizeText(req.params.vodId || '', 120);
  const pl = customPlaylists[id];
  if (!pl) return res.status(404).send('Playlist not found');
  const deliveryMode = normalizePlaylistDeliveryMode(pl.delivery_mode || pl.mode);
  const meta = getPlaylistRequestMeta(req, { mode: deliveryMode });
  const uaPolicy = enforcePlaylistUserAgentPolicy(req, pl, id, `vod:${vodId}`);
  if (!uaPolicy.ok) return res.status(403).send('User-Agent nuk lejohet për këtë playlist.');
  const allowedVod = new Set((pl.vod_items || []).map(v => sanitizeText(v, 120)).filter(Boolean));
  if (!allowedVod.has(vodId)) return res.status(404).send('VOD not in playlist');
  const item = findVodItemById(vodId);
  if (!item) return res.status(404).send('VOD not found');
  recordPlaylistAnalyticsEvent(id, {
    type: 'vod_click',
    target: vodId,
    mode: deliveryMode,
    ...meta
  });
  const token = issueVodStreamToken(vodId, req, 2 * 60);
  if (!token) return res.status(403).send('Token error');
  return res.redirect(302, `${BASE_PATH}/vod/link/${encodeURIComponent(token)}`);
});
router.get('/private-playlist/:id.m3u', requirePrivatePlaylistAuth, (req, res) => {
  return res.redirect(`${BASE_PATH}/playlist/${encodeURIComponent(req.params.id)}.m3u`);
});
