router.get('/admin/bandwidth', requireLogin, (req, res) => {
  if (!getFeatureFlags().bandwidth_dashboard) return res.status(404).send('Bandwidth dashboard është OFF.');
  const rows = Object.entries(bandwidthByChannel.channels || {})
    .map(([slug, row]) => {
      const bytes = Math.max(0, Number(row?.bytes || 0) || 0);
      const mb = bytes / (1024 * 1024);
      const gb = bytes / (1024 * 1024 * 1024);
      return {
        slug,
        name: allCombined[slug]?.name || slug,
        bytes,
        mb,
        gb,
        segments: Math.max(0, parseInt(row?.segments, 10) || 0),
        updatedAt: Number(row?.updated_at || 0) || 0
      };
    })
    .sort((a, b) => b.bytes - a.bytes)
    .slice(0, 50);
  const maxBytes = rows.length ? rows[0].bytes : 1;
  const listHtml = rows.map((row, idx) => {
    const width = Math.max(2, Math.round((row.bytes / maxBytes) * 100));
    return `<tr>
<td style="padding:8px 6px">${idx + 1}</td>
<td style="padding:8px 6px"><b>${row.name}</b><div style="font-size:.64rem;color:var(--muted)">${row.slug}</div></td>
<td style="padding:8px 6px">${row.segments}</td>
<td style="padding:8px 6px">${row.gb >= 1 ? `${row.gb.toFixed(2)} GB` : `${row.mb.toFixed(2)} MB`}</td>
<td style="padding:8px 6px"><div style="height:8px;border-radius:999px;background:rgba(255,255,255,.08);overflow:hidden"><div style="height:8px;width:${width}%;background:linear-gradient(90deg,var(--accent),var(--purple))"></div></div></td>
<td style="padding:8px 6px;color:var(--muted);font-size:.66rem">${row.updatedAt ? new Date(row.updatedAt).toLocaleString('sq-AL') : '-'}</td>
</tr>`;
  }).join('') || `<tr><td colspan="6" style="padding:16px;color:var(--muted)">Nuk ka të dhëna bandwidth ende.</td></tr>`;
  res.send(`<!DOCTYPE html><html lang="sq"><head>${BASE_STYLE}<title>Admin - Bandwidth</title></head><body>
${NAV_ADMIN}
<div class="page">
<div class="page-header">
<a href="${BASE_PATH}/admin/features" style="color:var(--muted)"><i class="fas fa-arrow-left"></i></a>
<i class="fas fa-chart-line" style="color:var(--accent)"></i><h2>Bandwidth per Kanal</h2>
<span class="badge">${rows.length} rows</span>
</div>
<div class="admin-section">
<h3><i class="fas fa-network-wired"></i> Top channels by bytes proxied</h3>
<table class="users-table"><thead><tr><th>#</th><th>Kanal</th><th>Segments</th><th>Traffic</th><th>Relative</th><th>Updated</th></tr></thead><tbody>${listHtml}</tbody></table>
</div>
</div></body></html>`);
});

