// ═══════════════════════════════════════════════════════════════════════════════
// ─── ADMIN CUSTOM CHANNELS ────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════
router.get('/admin/channels', requireLogin, (req, res) => {
  const success = req.query.success;
  const error   = req.query.error;

  // Build searchable channel list from all sources (not custom)
  const allApiChannels = [
    ...Object.entries(allChannelsDb).map(([slug,ch]) => ({ slug, name: ch.name, url: ch.url, src: ch.source === 'open_source' ? 'Open Source' : 'TV API' })),
    ...Object.entries(sportsDb).map(([slug,ch]) => ({ slug, name: ch.name, url: ch.url, src: ch.source === 'open_source' ? 'Open Source Sport' : 'Sport API' })),
    ...Object.entries(nimiChannelsDb).map(([slug,ch]) => ({ slug, name: ch.name, url: ch.url, src: 'Nimi API' })),
  ].sort((a,b) => a.name.localeCompare(b.name));
  const manualEpgSettings = normalizeManualEpgConfig(appConfig.manual_epg);
  appConfig.manual_epg = manualEpgSettings;

  function renderCustomList(cat, label, color, icon) {
    const chs = [...(customChannels[cat] || [])].sort((a, b) => Number(a.order || 0) - Number(b.order || 0));
    const rows = chs.map((ch, i) => {
      const slug = createSlug(ch.slug || '') || ('custom_' + createSlug(ch.name) + '_' + md5(ch.url || ch.name));
      const logo = String(ch.logo || '').trim();
      const backupUrls = normalizeBackupUrls(ch.backup_urls || []);
      const youtubeUrl = normalizeUrlExact(ch.youtube_url || '');
      const embedUrl = normalizeUrlExact(ch.embed_url || '');
      const manualEpgUrl = getManualEpgUrlForSlug(slug);
      const userAgent = String(ch.user_agent || ch.userAgent || '').trim();
      const upstreamHeaders = ch.upstream_headers && typeof ch.upstream_headers === 'object' ? ch.upstream_headers : {};
      const referer = String(upstreamHeaders.Referer || '').trim();
      const origin = String(upstreamHeaders.Origin || '').trim();
      const cookie = String(upstreamHeaders.Cookie || '').trim();
      const xForwardedFor = String(upstreamHeaders['X-Forwarded-For'] || '').trim();
      const safeLogoAttr = logo.replace(/"/g, '&quot;');
      const logoBadge = logo
        ? `<img src="${safeLogoAttr}" alt="logo" style="width:38px;height:38px;border-radius:8px;object-fit:cover;border:1px solid var(--border)" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><div style="display:none;width:38px;height:38px;border-radius:8px;background:rgba(255,255,255,.04);align-items:center;justify-content:center;border:1px solid var(--border);color:var(--muted)"><i class="fas fa-image"></i></div>`
        : `<div style="width:38px;height:38px;border-radius:8px;background:rgba(255,255,255,.04);display:flex;align-items:center;justify-content:center;border:1px solid var(--border);color:var(--muted)"><i class="fas fa-image"></i></div>`;
      return `
<div class="playlist-card" style="flex-direction:column;align-items:stretch;gap:8px">
<div style="display:flex;align-items:center;gap:10px">
  <div>${logoBadge}</div>
  <div style="flex:1">
    <div style="font-weight:600"><span style="display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:5px;background:rgba(255,255,255,.06);font-size:.7rem;margin-right:4px;color:var(--muted)">${i + 1}</span><i class="fas fa-${icon}" style="color:${color}"></i> ${ch.name}</div>
    <div style="font-family:monospace;font-size:.62rem;color:var(--muted);margin-top:2px;word-break:break-all">${ch.url}</div>
    ${backupUrls.length ? `<div style="font-family:monospace;font-size:.58rem;color:var(--muted);margin-top:2px;word-break:break-all">backup: ${backupUrls.join(' | ')}</div>` : ''}
    ${youtubeUrl ? `<div style="font-family:monospace;font-size:.58rem;color:var(--muted);margin-top:2px;word-break:break-all">yt: ${youtubeUrl}</div>` : ''}
    ${embedUrl ? `<div style="font-family:monospace;font-size:.58rem;color:var(--muted);margin-top:2px;word-break:break-all">embed: ${embedUrl}</div>` : ''}
    ${userAgent ? `<div style="font-family:monospace;font-size:.58rem;color:var(--muted);margin-top:2px;word-break:break-all">UA: ${userAgent}</div>` : ''}
    ${referer ? `<div style="font-family:monospace;font-size:.58rem;color:var(--muted);margin-top:2px;word-break:break-all">Referer: ${referer}</div>` : ''}
    ${origin ? `<div style="font-family:monospace;font-size:.58rem;color:var(--muted);margin-top:2px;word-break:break-all">Origin: ${origin}</div>` : ''}
    ${cookie ? `<div style="font-family:monospace;font-size:.58rem;color:var(--muted);margin-top:2px;word-break:break-all">Cookie: ${cookie.slice(0, 120)}${cookie.length > 120 ? '…' : ''}</div>` : ''}
    ${xForwardedFor ? `<div style="font-family:monospace;font-size:.58rem;color:var(--muted);margin-top:2px;word-break:break-all">X-Forwarded-For: ${xForwardedFor}</div>` : ''}
    <div id="customEpgBadge_${cat}_${slug}" style="font-size:.62rem;color:var(--muted);margin-top:2px">manual epg: <b>${manualEpgUrl ? 'ON' : 'OFF'}</b></div>
    <div style="font-family:monospace;font-size:.58rem;color:var(--muted);margin-top:2px">slug: ${slug}</div>
  </div>
  <div style="display:flex;gap:6px;flex-shrink:0">
    <button class="a-btn a-btn-primary" style="padding:4px 8px;font-size:.7rem" onclick="reorderChannel('${cat}','${slug}','up')" title="Ngri lart"><i class="fas fa-arrow-up"></i></button>
    <button class="a-btn a-btn-primary" style="padding:4px 8px;font-size:.7rem" onclick="reorderChannel('${cat}','${slug}','down')" title="Zbrit poshtë"><i class="fas fa-arrow-down"></i></button>
    <select onchange="moveChannel('${cat}','${slug}',this.value)" style="background:var(--card);border:1px solid var(--border);color:var(--text);border-radius:6px;padding:4px 8px;font-size:.7rem">
      <option value="">📦 Lëviz...</option>
      ${cat!=='tv'?`<option value="tv">→ TV</option>`:''}
      ${cat!=='sport'?`<option value="sport">→ Sport</option>`:''}
      ${cat!=='nimi'?`<option value="nimi">→ Nimi</option>`:''}
    </select>
    <button class="a-btn a-btn-green" style="padding:4px 10px;font-size:.7rem" onclick='setCustomManualEpg(${JSON.stringify(cat)},${JSON.stringify(slug)},${JSON.stringify(manualEpgUrl)})'><i class="fas fa-tv"></i> EPG</button>
    <button class="a-btn a-btn-orange" style="padding:4px 10px;font-size:.7rem" onclick='editChannel(${JSON.stringify(cat)},${JSON.stringify(slug)},${JSON.stringify(ch.name)},${JSON.stringify(ch.url)},${JSON.stringify(logo)},${JSON.stringify(backupUrls)},${JSON.stringify(youtubeUrl)},${JSON.stringify(embedUrl)},${JSON.stringify(userAgent)},${JSON.stringify(referer)},${JSON.stringify(origin)},${JSON.stringify(cookie)},${JSON.stringify(xForwardedFor)})'><i class="fas fa-pen"></i></button>
    <button class="a-btn a-btn-red" style="padding:4px 10px;font-size:.7rem" onclick='deleteChannel(${JSON.stringify(cat)},${JSON.stringify(slug)},${JSON.stringify(ch.name)})'><i class="fas fa-trash"></i></button>
  </div>
</div>
</div>`;
    }).join('') || `<p style="color:var(--muted);text-align:center;padding:16px">Nuk ka kanale të shtuara në ${label}.</p>`;
    return `<div class="admin-section">
<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap">
<h3><i class="fas fa-${icon}" style="color:${color}"></i> ${label} <span class="badge" style="margin-left:8px">${chs.length} kanale</span></h3>
<button class="a-btn a-btn-red" style="font-size:.72rem;padding:6px 10px" onclick="clearCustomChannels('${cat}')"><i class="fas fa-trash-alt"></i> Fshi të gjitha ${label}</button>
</div>
${rows}
<div style="border-top:1px solid var(--border);padding-top:14px;margin-top:12px">
<div style="display:flex;gap:6px;margin-bottom:10px">
  <button class="a-btn a-btn-green" style="font-size:.75rem" onclick="showManual('${cat}')"><i class="fas fa-keyboard"></i> Shto Manual</button>
  <button class="a-btn a-btn-primary" style="font-size:.75rem" onclick="showPicker('${cat}')"><i class="fas fa-search"></i> Zgjidh nga Lista</button>
</div>
<div id="manual_${cat}" style="display:none">
  <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px">
    <input type="text" id="name_${cat}" class="form-input" placeholder="Emri i kanalit" style="flex:1;min-width:140px;margin:0">
    <input type="text" id="url_${cat}" class="form-input" placeholder="URL (https://...m3u8)" style="flex:2;min-width:180px;margin:0">
    <input type="text" id="backup_${cat}" class="form-input" placeholder="Backup links (ndarë me | )" style="flex:1.5;min-width:180px;margin:0">
    <input type="text" id="youtube_${cat}" class="form-input" placeholder="YouTube URL (opsionale)" style="flex:1.4;min-width:180px;margin:0">
    <input type="text" id="embed_${cat}" class="form-input" placeholder="Embed URL (opsionale)" style="flex:1.4;min-width:180px;margin:0">
    <input type="text" id="logo_${cat}" class="form-input" placeholder="Logo URL (opsionale)" style="flex:1.2;min-width:160px;margin:0">
  </div>
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:6px;margin-bottom:6px">
    <input type="text" id="ua_${cat}" class="form-input" placeholder="User-Agent (p.sh. KanaliImUA)" style="margin:0">
    <input type="text" id="referer_${cat}" class="form-input" placeholder="Referer (opsionale)" style="margin:0">
    <input type="text" id="origin_${cat}" class="form-input" placeholder="Origin (opsionale)" style="margin:0">
    <input type="text" id="cookie_${cat}" class="form-input" placeholder="Cookie (opsionale)" style="margin:0">
    <input type="text" id="xff_${cat}" class="form-input" placeholder="X-Forwarded-For (p.sh. 1.2.3.4)" style="margin:0">
    <button class="a-btn a-btn-green" onclick="addChannel('${cat}')" style="align-self:end"><i class="fas fa-plus"></i> Shto</button>
  </div>
</div>
<div id="picker_${cat}" style="display:none">
  <input type="text" class="form-input" placeholder="Kërko kanal nga API..." oninput="filterPicker('${cat}',this.value)" style="margin-bottom:8px">
  <div id="pickerList_${cat}" style="max-height:250px;overflow-y:auto;background:var(--card);border-radius:8px;border:1px solid var(--border)"></div>
</div>
</div>
</div>`;
  }

  const allChannelsJson = JSON.stringify(allApiChannels).replace(/`/g,'\\`').replace(/\\/g,'\\\\').replace(/"/g,'\\"');

  res.send(`<!DOCTYPE html><html lang="sq">
<head>${BASE_STYLE}<title>Admin - Kanale</title></head><body>
${NAV_ADMIN.replace('href="${BASE_PATH}/admin/channels" class="nav-link"', 'href="${BASE_PATH}/admin/channels" class="nav-link active"')}
<div class="page">
<div class="page-header">
<a href="${BASE_PATH}/admin" style="color:var(--muted)"><i class="fas fa-arrow-left"></i></a>
<i class="fas fa-plus-circle" style="color:var(--accent)"></i><h2>Menaxho Kanalet Custom</h2>
<span class="badge">${(customChannels.tv||[]).length+(customChannels.sport||[]).length+(customChannels.nimi||[]).length} total</span>
</div>
${success ? `<div style="background:rgba(0,200,83,.1);border:1px solid var(--green);color:var(--green);padding:12px;border-radius:8px;margin-bottom:16px"><i class="fas fa-check-circle"></i> ${success}</div>` : ''}
${error   ? `<div style="background:rgba(255,68,68,.1);border:1px solid var(--red);color:var(--red);padding:12px;border-radius:8px;margin-bottom:16px"><i class="fas fa-exclamation-circle"></i> ${error}</div>` : ''}
<div style="background:rgba(0,212,255,.05);border:1px solid rgba(0,212,255,.2);border-radius:8px;padding:10px 14px;margin-bottom:16px;font-size:.78rem;color:var(--muted)">
<i class="fas fa-info-circle" style="color:var(--accent)"></i> Mund të shtosh kanale me URL manual ose të zgjedhësh nga lista API. URL-të pa .m3u8 (p.sh. .../1) konvertohen automatikisht në .m3u8.
<br><i class="fas fa-shield-alt" style="color:var(--purple)"></i> Për stream që kërkojnë kushte speciale, vendos <b>User-Agent</b>, <b>Referer</b>, <b>Origin</b>, <b>Cookie</b>, <b>X-Forwarded-For</b> te shtimi manual.
<br><i class="fas fa-tv" style="color:var(--sport)"></i> Për çdo kanal custom (TV/Sport/Nimi) mund të vendosësh edhe link manual EPG me butonin <b>EPG</b>.
</div>
<div class="admin-section">
<h3><i class="fas fa-bolt"></i> Veprime të Shpejta</h3>
<div style="display:flex;gap:8px;flex-wrap:wrap">
  <button class="a-btn a-btn-red" onclick="clearCustomChannels('all')"><i class="fas fa-trash-alt"></i> Fshi të gjitha kanalet custom</button>
  <a class="a-btn a-btn-primary" href="${BASE_PATH}/admin/categories/all-channels"><i class="fas fa-layer-group"></i> Edit kanalet e upload/API</a>
  <a class="a-btn a-btn-green" href="${BASE_PATH}/admin/channel-access"><i class="fas fa-crown"></i> Normal / Premium me tick</a>
</div>
<p style="color:var(--muted);font-size:.74rem;margin-top:8px">Për kanalet që vijnë nga upload playlist/API, përdor “Edit kanalet e upload/API”.</p>
</div>
${renderCustomList('tv','TV Kanale','var(--accent)','tv')}
${renderCustomList('sport','Sport','var(--sport)','futbol')}
${renderCustomList('nimi','Nimi','var(--purple)','shield-alt')}
</div>
<script>
const BASE='${BASE_PATH}';
const ATOKEN='${ADMIN_TOKEN}';
const allCh=${JSON.stringify(allApiChannels)};
function postJson(url, body){
  return fetch(url,{
    method:'POST',
    headers:{'Content-Type':'application/json','x-admin-token':ATOKEN},
    credentials:'include',
    body:JSON.stringify(body||{})
  }).then(async r=>{
    const data=await r.json().catch(()=>({ok:false,error:'Invalid JSON'}));
    if(!r.ok||data.ok===false){
      throw new Error(data.error||('HTTP '+r.status));
    }
    return data;
  });
}

function showManual(cat){
  const m=document.getElementById('manual_'+cat);
  const p=document.getElementById('picker_'+cat);
  m.style.display=m.style.display==='none'?'block':'none';
  p.style.display='none';
}
function showPicker(cat){
  const p=document.getElementById('picker_'+cat);
  const m=document.getElementById('manual_'+cat);
  p.style.display=p.style.display==='none'?'block':'none';
  m.style.display='none';
  if(p.style.display==='block') renderPickerList(cat,'');
}
function filterPicker(cat,q){
  renderPickerList(cat,q.toLowerCase());
}
function renderPickerList(cat,q){
  const filtered=allCh.filter(c=>c.name.toLowerCase().includes(q)||c.src.toLowerCase().includes(q)).slice(0,80);
  const container=document.getElementById('pickerList_'+cat);
  if(!filtered.length){container.innerHTML='<p style="color:var(--muted);padding:12px;text-align:center">Nuk u gjet asgjë.</p>';return;}
  container.innerHTML=filtered.map(c=>\`
<div style="display:flex;align-items:center;gap:8px;padding:8px 12px;border-bottom:1px solid var(--border);cursor:pointer" onmouseenter="this.style.background='rgba(255,255,255,.04)'" onmouseleave="this.style.background=''">
<div style="flex:1">
  <div style="font-size:.8rem;font-weight:600">\${c.name}</div>
  <div style="font-size:.6rem;color:var(--muted)">\${c.src}</div>
</div>
<button class="a-btn a-btn-green" type="button" style="padding:3px 10px;font-size:.68rem" onclick='addFromList(\${JSON.stringify(cat)},\${JSON.stringify(c.name)},\${JSON.stringify(c.url)})'><i class="fas fa-plus"></i> Shto</button>
</div>
\`).join('');
}
function addFromList(cat,name,url){
  doAdd(cat,name,url);
}
function addChannel(cat){
  const name=document.getElementById('name_'+cat).value.trim();
  const url=document.getElementById('url_'+cat).value.trim();
  const backupRaw=document.getElementById('backup_'+cat).value.trim();
  const youtubeUrl=document.getElementById('youtube_'+cat).value.trim();
  const embedUrl=document.getElementById('embed_'+cat).value.trim();
  const logo=document.getElementById('logo_'+cat).value.trim();
  const userAgent=document.getElementById('ua_'+cat).value.trim();
  const referer=document.getElementById('referer_'+cat).value.trim();
  const origin=document.getElementById('origin_'+cat).value.trim();
  const cookie=document.getElementById('cookie_'+cat).value.trim();
  const xForwardedFor=document.getElementById('xff_'+cat).value.trim();
  if(!name||!url){alert('Emri dhe URL janë të detyrueshëm!');return;}
  doAdd(cat,name,url,logo,backupRaw,youtubeUrl,embedUrl,userAgent,referer,origin,cookie,xForwardedFor);
}
function parseBackupLinks(raw){
  return String(raw||'').split('|').map(v=>v.trim()).filter(Boolean).slice(0,5);
}
function doAdd(cat,name,url,logo='',backupRaw='',youtubeUrl='',embedUrl='',userAgent='',referer='',origin='',cookie='',xForwardedFor=''){
  postJson(BASE+'/api/custom-channel/add',{
    name,url,logo,category:cat,
    backup_urls:parseBackupLinks(backupRaw),
    youtube_url:youtubeUrl,
    embed_url:embedUrl,
    user_agent:userAgent,
    upstream_referer:referer,
    upstream_origin:origin,
    upstream_cookie:cookie,
    upstream_x_forwarded_for:xForwardedFor
  })
    .then(()=>location.reload())
    .catch(e=>alert('Gabim: '+e.message));
}
function setCustomManualEpg(cat,slug,currentUrl){
  const next=prompt('Vendos link manual EPG për këtë kanal custom (lëre bosh për remove):',String(currentUrl||''));
  if(next===null) return;
  const epgUrl=String(next||'').trim();
  postJson(BASE+'/api/admin/channel-epg-link',{slug,epg_url:epgUrl})
    .then(()=>{
      const badge=document.getElementById('customEpgBadge_'+cat+'_'+slug);
      if(badge) badge.innerHTML='manual epg: <b>'+(epgUrl?'ON':'OFF')+'</b>';
      alert(epgUrl?'EPG u ruajt.':'EPG u hoq.');
      setTimeout(()=>location.reload(),300);
    })
    .catch(e=>alert('Gabim EPG: '+e.message));
}
function clearCustomChannels(category){
  const isAll=category==='all';
  const label=isAll?'të gjitha kanalet custom':('kanalet custom te '+category.toUpperCase());
  if(!confirm('Je i sigurt që do të fshihen '+label+'?')) return;
  postJson(BASE+'/api/custom-channel/clear',{category})
    .then(()=>location.reload())
    .catch(e=>alert('Gabim: '+e.message));
}
function deleteChannel(cat,slug,name){
  if(!confirm('Fshi "'+name+'"?')) return;
  postJson(BASE+'/api/custom-channel/delete',{category:cat,slug})
    .then(()=>location.reload())
    .catch(e=>alert('Gabim: '+e.message));
}
function moveChannel(fromCat,slug,toCat){
  if(!toCat) return;
  postJson(BASE+'/api/custom-channel/move',{from_category:fromCat,to_category:toCat,slug})
    .then(()=>location.reload())
    .catch(e=>alert('Gabim: '+e.message));
}
function reorderChannel(cat,slug,direction){
  postJson(BASE+'/api/custom-channel/reorder',{category:cat,slug,direction})
    .then(()=>location.reload())
    .catch(e=>alert('Gabim: '+e.message));
}
function editChannel(cat,slug,currentName,currentUrl,currentLogo,currentBackups,currentYoutubeUrl,currentEmbedUrl,currentUserAgent,currentReferer,currentOrigin,currentCookie,currentXForwardedFor){
  const name=(prompt('Emri i ri i kanalit:',currentName||'')||'').trim();
  if(!name) return;
  const url=(prompt('URL e re e kanalit:',currentUrl||'')||'').trim();
  if(!url) return alert('URL nuk mund të jetë bosh.');
  const backupPrompt=prompt('Backup links (ndarë me | ):',Array.isArray(currentBackups)?currentBackups.join(' | '):'');
  if(backupPrompt===null) return;
  const youtubePrompt=prompt('YouTube URL (opsionale):',currentYoutubeUrl||'');
  if(youtubePrompt===null) return;
  const embedPrompt=prompt('Embed URL (opsionale):',currentEmbedUrl||'');
  if(embedPrompt===null) return;
  const logoPrompt=prompt('Logo URL (opsionale):',currentLogo||'');
  if(logoPrompt===null) return;
  const uaPrompt=prompt('User-Agent (opsionale):',currentUserAgent||'');
  if(uaPrompt===null) return;
  const refererPrompt=prompt('Referer (opsionale):',currentReferer||'');
  if(refererPrompt===null) return;
  const originPrompt=prompt('Origin (opsionale):',currentOrigin||'');
  if(originPrompt===null) return;
  const cookiePrompt=prompt('Cookie (opsionale):',currentCookie||'');
  if(cookiePrompt===null) return;
  const xffPrompt=prompt('X-Forwarded-For (opsionale, p.sh. 1.2.3.4):',currentXForwardedFor||'');
  if(xffPrompt===null) return;
  const logo=String(logoPrompt||'').trim();
  postJson(BASE+'/api/custom-channel/update',{
    category:cat,slug,name,url,logo,
    backup_urls:parseBackupLinks(backupPrompt),
    youtube_url:String(youtubePrompt||'').trim(),
    embed_url:String(embedPrompt||'').trim(),
    user_agent:String(uaPrompt||'').trim(),
    upstream_referer:String(refererPrompt||'').trim(),
    upstream_origin:String(originPrompt||'').trim(),
    upstream_cookie:String(cookiePrompt||'').trim(),
    upstream_x_forwarded_for:String(xffPrompt||'').trim()
  })
    .then(()=>location.reload())
    .catch(e=>alert('Gabim: '+e.message));
}
</script>
</body></html>`);
});

router.get('/admin/channel-access', requireLogin, (req, res) => {
  const success = String(req.query.success || '').trim();
  const error = String(req.query.error || '').trim();
  const sorted = Object.entries(allCombined).sort((a, b) => String(a[1]?.name || '').localeCompare(String(b[1]?.name || '')));
  const sourceLabelOf = (slug, channel) => SOURCE_LABELS[getChannelSourceKey(channel)] || getChannelSourceKey(channel) || '-';
  const tierMap = normalizeChannelAccessTierMap(appConfig.channel_access_tiers || {});
  const normalSet = new Set();
  const premiumSet = new Set();
  for (const [slug] of sorted) {
    const tier = normalizeChannelAccessTier(tierMap[slug] || 'all');
    if (tier === 'normal') normalSet.add(slug);
    else if (tier === 'premium') premiumSet.add(slug);
    else {
      normalSet.add(slug);
      premiumSet.add(slug);
    }
  }
  const renderRows = (kind = 'normal') => sorted.map(([slug, channel]) => {
    const checked = kind === 'premium' ? premiumSet.has(slug) : normalSet.has(slug);
    const safeName = escapeHtml(String(channel?.name || slug));
    const safeSlug = escapeHtmlAttr(slug);
    const sourceLabel = escapeHtml(sourceLabelOf(slug, channel));
    return `<label class="channel-checkbox-item channel-access-item" data-name="${escapeHtmlAttr(String(channel?.name || '').toLowerCase())}" style="display:flex;align-items:center;gap:8px">
<input type="checkbox" name="${kind}_channels" value="${safeSlug}" ${checked ? 'checked' : ''}>
<span style="flex:1;min-width:0">
<span style="display:block;font-weight:600">${safeName}</span>
<span style="display:block;font-size:.66rem;color:var(--muted)">${sourceLabel}</span>
</span>
</label>`;
  }).join('');
  res.send(`<!DOCTYPE html><html lang="sq">
<head>${BASE_STYLE}<title>Admin - Channel Access</title></head><body>
${NAV_ADMIN.replace('href="${BASE_PATH}/admin/channel-access" class="nav-link"', 'href="${BASE_PATH}/admin/channel-access" class="nav-link active"')}
<div class="page">
<div class="page-header">
<a href="${BASE_PATH}/admin" style="color:var(--muted)"><i class="fas fa-arrow-left"></i></a>
<i class="fas fa-crown" style="color:var(--sport)"></i><h2>Channel Access: Normal / Premium</h2>
<span class="badge">${sorted.length} kanale</span>
</div>
${success ? `<div style="background:rgba(0,200,83,.1);border:1px solid var(--green);color:var(--green);padding:12px;border-radius:8px;margin-bottom:16px"><i class="fas fa-check-circle"></i> ${escapeHtml(success)}</div>` : ''}
${error ? `<div style="background:rgba(255,68,68,.1);border:1px solid var(--red);color:var(--red);padding:12px;border-radius:8px;margin-bottom:16px"><i class="fas fa-exclamation-circle"></i> ${escapeHtml(error)}</div>` : ''}
<div class="admin-section">
<h3><i class="fas fa-info-circle"></i> Si funksionon</h3>
<p style="color:var(--muted);font-size:.78rem;line-height:1.5">
Tick te <b>Normal</b> = kanali hapet vetëm për user normal.<br>
Tick te <b>Premium</b> = kanali hapet vetëm për user premium.<br>
Nëse e bën tick te të dyja, kanali hapet për të dyja paketat.
</p>
</div>
<form method="POST" action="${BASE_PATH}/admin/channel-access">
<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
  <section class="admin-section">
    <h3><i class="fas fa-user"></i> Paketa Normal</h3>
    <input id="normalSearch" class="form-input" style="margin-bottom:8px" placeholder="Kërko kanal normal..." oninput="filterChannelAccess('normal',this.value)">
    <div id="normalList" style="max-height:62vh;overflow:auto;display:grid;gap:6px">${renderRows('normal')}</div>
  </section>
  <section class="admin-section">
    <h3><i class="fas fa-crown"></i> Paketa Premium</h3>
    <input id="premiumSearch" class="form-input" style="margin-bottom:8px" placeholder="Kërko kanal premium..." oninput="filterChannelAccess('premium',this.value)">
    <div id="premiumList" style="max-height:62vh;overflow:auto;display:grid;gap:6px">${renderRows('premium')}</div>
  </section>
</div>
<div class="admin-bar" style="justify-content:flex-end;margin-top:12px;position:sticky;bottom:10px;background:var(--surface);padding:8px;border:1px solid var(--border);border-radius:10px">
  <button type="submit" class="a-btn a-btn-primary"><i class="fas fa-save"></i> Ruaj Channel Access</button>
</div>
</form>
</div>
<script>
function filterChannelAccess(kind,q){
  const text=String(q||'').toLowerCase().trim();
  const root=document.getElementById(kind+'List');
  if(!root) return;
  root.querySelectorAll('.channel-access-item').forEach(item=>{
    const key=String(item.getAttribute('data-name')||'').toLowerCase();
    item.style.display=!text||key.includes(text)?'':'none';
  });
}
</script>
</body></html>`);
});

router.post('/admin/channel-access', requireLogin, (req, res) => {
  const allSlugs = new Set(Object.keys(allCombined));
  const normalIncoming = Array.isArray(req.body?.normal_channels) ? req.body.normal_channels : (req.body?.normal_channels ? [req.body.normal_channels] : []);
  const premiumIncoming = Array.isArray(req.body?.premium_channels) ? req.body.premium_channels : (req.body?.premium_channels ? [req.body.premium_channels] : []);
  const normalSet = new Set(normalIncoming.map(v => createSlug(v || '')).filter(slug => !!slug && allSlugs.has(slug)));
  const premiumSet = new Set(premiumIncoming.map(v => createSlug(v || '')).filter(slug => !!slug && allSlugs.has(slug)));
  const nextMap = {};
  for (const slug of allSlugs) {
    const inNormal = normalSet.has(slug);
    const inPremium = premiumSet.has(slug);
    if (inNormal && inPremium) continue;
    if (inNormal) nextMap[slug] = 'normal';
    else if (inPremium) nextMap[slug] = 'premium';
  }
  appConfig.channel_access_tiers = normalizeChannelAccessTierMap(nextMap);
  saveJSON(CONFIG_FILE, appConfig);
  appendAuditLog('save_channel_access_bulk', req, {
    normal_only: Object.values(appConfig.channel_access_tiers).filter(v => v === 'normal').length,
    premium_only: Object.values(appConfig.channel_access_tiers).filter(v => v === 'premium').length
  });
  return res.redirect(`${BASE_PATH}/admin/channel-access?success=${encodeURIComponent('Channel access u ruajt me sukses!')}`);
});

