router.post('/admin/categories', requireLogin, (req, res) => {
  const action = req.body.action;
  if (action === 'move_order') {
    const id = String(req.body.category_id || '').trim();
    const direction = String(req.body.direction || '').trim().toLowerCase();
    if (!id || !customCategories[id]) return res.redirect(`${BASE_PATH}/admin/categories?error=Kategoria+nuk+u+gjet`);
    const list = Object.entries(customCategories).sort((a, b) => (Number(a[1].order || 0) - Number(b[1].order || 0)) || a[1].name.localeCompare(b[1].name));
    const idx = list.findIndex(([cid]) => cid === id);
    if (idx < 0) return res.redirect(`${BASE_PATH}/admin/categories`);
    const swapWith = direction === 'up' ? idx - 1 : idx + 1;
    if (swapWith < 0 || swapWith >= list.length) return res.redirect(`${BASE_PATH}/admin/categories`);
    const tmp = list[idx];
    list[idx] = list[swapWith];
    list[swapWith] = tmp;
    list.forEach(([cid], i) => { customCategories[cid].order = i + 1; });
    customCategories = normalizeCustomCategories(customCategories);
    saveJSON(CATEGORIES_FILE, customCategories);
    return res.redirect(`${BASE_PATH}/admin/categories?success=Renditja+u+ruajt`);
  }
  if (action === 'create') {
    const name = (req.body.category_name || '').trim();
    if (!name) return res.redirect(`${BASE_PATH}/admin/categories?error=Emri+nuk+mund+të+jetë+bosh!`);
    const id = createSlug(name);
    if (!id) return res.redirect(`${BASE_PATH}/admin/categories?error=Emri+është+i+pavlefshëm!`);
    if (customCategories[id]) return res.redirect(`${BASE_PATH}/admin/categories?error=Kjo+kategori+ekziston!`);
    const maxOrder = Object.values(customCategories).reduce((m, c) => Math.max(m, Number(c.order || 0)), 0);
    customCategories[id] = {
      name,
      logo: normalizeHttpUrl(req.body.category_logo || ''),
      channels: [],
      created: new Date().toISOString().slice(0, 16).replace('T', ' '),
      showOnMain: true,
      order: maxOrder + 1
    };
    saveJSON(CATEGORIES_FILE, customCategories);
    return res.redirect(`${BASE_PATH}/admin/categories?success=Kategoria+u+krijua!`);
  }
  if (action === 'toggle_visibility') {
    const id = String(req.body.category_id || '');
    if (customCategories[id]) {
      customCategories[id].showOnMain = readCheckboxField(req.body.show_on_main);
      saveJSON(CATEGORIES_FILE, customCategories);
      return res.redirect(`${BASE_PATH}/admin/categories?success=Shfaqja+në+main+menu+u+ndryshua!`);
    }
    return res.redirect(`${BASE_PATH}/admin/categories?error=Kategoria+nuk+u+gjet!`);
  }
  if (action === 'toggle_system_visibility') {
    const key = String(req.body.category_key || '').trim();
    const normalized = normalizeCategoryVisibility(appConfig.category_visibility);
    if (!Object.prototype.hasOwnProperty.call(normalized, key)) {
      return res.redirect(`${BASE_PATH}/admin/categories?error=Çelës+kategorie+i+pavlefshëm!`);
    }
    normalized[key] = readCheckboxField(req.body.show_on_main);
    appConfig.category_visibility = normalizeCategoryVisibility(normalized);
    saveJSON(CONFIG_FILE, appConfig);
    return res.redirect(`${BASE_PATH}/admin/categories?success=Kategoria+sistem+u+ndryshua!`);
  }
  if (action === 'delete') {
    const id = req.body.category_id;
    if (customCategories[id]) {
      delete customCategories[id];
      saveJSON(CATEGORIES_FILE, customCategories);
    }
    return res.redirect(`${BASE_PATH}/admin/categories?success=Kategoria+u+fshi!`);
  }
  res.redirect(`${BASE_PATH}/admin/categories`);
});

