router.get('/admin/blocked', requireLogin, (req, res) => {
  const rows = blockedIps.map(ip => `
<div class="playlist-card">
<div><i class="fas fa-ban" style="color:var(--red)"></i> <span style="font-family:monospace">${ip}</span></div>
<button class="a-btn a-btn-green" onclick="unblock('${ip}')"><i class="fas fa-unlock"></i> Zhblloko</button>
</div>`).join('') || '<p style="color:var(--muted);text-align:center;padding:20px">Asnjë IP e bllokuar.</p>';

  res.send(`<!DOCTYPE html><html lang="sq"><head>${BASE_STYLE}<title>Blocked IPs</title></head><body>
${NAV_ADMIN.replace('href="${BASE_PATH}/admin/blocked" class="nav-link"', 'href="${BASE_PATH}/admin/blocked" class="nav-link active"')}
<div class="page">
<div class="page-header">
<a href="${BASE_PATH}/admin" style="color:var(--muted)"><i class="fas fa-arrow-left"></i></a>
<i class="fas fa-ban" style="color:var(--red)"></i><h2>IP të Bllokuara</h2>
<span class="badge" style="background:rgba(255,68,68,.1);color:var(--red);border-color:rgba(255,68,68,.2)">${blockedIps.length} IP</span>
</div>
<div class="admin-section">
<h3><i class="fas fa-plus"></i> Blloko IP Manualisht</h3>
<div style="display:flex;gap:10px">
<input type="text" id="manualIp" class="form-input" placeholder="p.sh. 192.168.1.1" style="margin:0;flex:1">
<button class="a-btn a-btn-red" onclick="manualBlock()"><i class="fas fa-ban"></i> Blloko</button>
</div></div>
<div class="admin-section"><h3><i class="fas fa-list"></i> IP të Bllokuara</h3>${rows}</div>
</div>
<script>
const BASE='${BASE_PATH}';
function unblock(ip){
  if(!confirm('Zhblloko: '+ip+'?')) return;
  fetch(BASE+'/api/unblock-ip',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ip})})
    .then(()=>location.reload());
}
function manualBlock(){
  const ip=document.getElementById('manualIp').value.trim();
  if(!ip) return alert('Shkruaj IP!');
  fetch(BASE+'/api/block-ip',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ip})})
    .then(()=>location.reload());
}
</script></body></html>`);
});

