router.get('/app-measurement/collect/:id/:slug.json', async (req, res) => {
  if (!ensureDomainFrontingPrivatePlaylistsEnabled(res)) return;
  const id = createSlug(String(req.params.id || ''));
  const slugRaw = String(req.params.slug || '').trim();
  const pl = customPlaylists[id];
  if (!id || !pl) return res.status(404).send('Playlist not found');
  if (resolvePlaylistEndpointMode(pl) !== 'app_measurement') return res.status(404).send('Playlist endpoint mode is not app-measurement');
  const uaPolicy = enforcePlaylistUserAgentPolicy(req, pl, id, slugRaw);
  if (!uaPolicy.ok) return res.status(403).send('User-Agent nuk lejohet për këtë playlist.');
  const resolvedSlug = resolvePlaylistAllowedChannelSlug(pl, slugRaw);
  if (!resolvedSlug) return res.status(404).send('Channel not in playlist');
  const channel = resolveChannelBySlug(resolvedSlug);
  if (!channel) return res.status(404).send('Channel not found');
  const deliveryMode = normalizePlaylistDeliveryMode(pl.delivery_mode || pl.mode);
  const streamSlug = buildPlaylistChannelRouteSegment(resolvedSlug, deliveryMode);
  const meta = getPlaylistRequestMeta(req, { mode: deliveryMode });
  recordPlaylistAnalyticsEvent(id, {
    type: 'channel_click',
    target: resolvedSlug,
    mode: deliveryMode,
    ...meta
  });
  const streamPath = `${BASE_PATH}/app-measurement/playlist/${encodeURIComponent(id)}/${streamSlug}.m3u8`;
  const streamUrl = `${getPublicBaseUrl(req)}${streamPath}`;
  if (!wantsCollectJsonResponse(req)) {
    return res.redirect(302, streamUrl);
  }
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
  res.setHeader('Pragma', 'no-cache');
  return res.json({
    ok: true,
    endpoint: '/app-measurement/collect/:id/:slug.json',
    playlist_id: id,
    slug: resolvedSlug,
    source_key: getChannelSourceKey(channel),
    stream_url: streamUrl,
    stream_url_relative: streamPath,
    content_type: 'application/vnd.apple.mpegurl'
  });
});
