let servicesCleanedUp = false;
let clusterReloadTimer = null;
let clusterReloadRunning = false;
function scheduleClusterReload(payload) {
  if (clusterReloadRunning) return;
  clearTimeout(clusterReloadTimer);
  clusterReloadTimer = setTimeout(async () => {
    if (clusterReloadRunning || updateDatabasesRunning) return;
    clusterReloadRunning = true;
    try {
      console.log(`[cluster-sync] reload requested (${payload?.reason || 'update'})`);
      const reason = String(payload?.reason || '');
      if (reason.startsWith('playlist_analytics') || reason.includes('playlist_analytics')) {
        // Disk mirror refresh for workers (Redis remains source of truth for reads).
        playlistAnalyticsState = normalizePlaylistAnalyticsState(loadJSON(PLAYLIST_ANALYTICS_FILE, {}));
        playlistAnalyticsStore.replaceMemoryState(playlistAnalyticsState);
      } else {
        await updateDatabasesInternal({ syncFromDisk: true });
        // Keep analytics mirror reasonably fresh on channel reloads too.
        playlistAnalyticsState = normalizePlaylistAnalyticsState(loadJSON(PLAYLIST_ANALYTICS_FILE, {}));
        playlistAnalyticsStore.replaceMemoryState(playlistAnalyticsState);
      }
    } catch (err) {
      console.warn('[cluster-sync] reload failed:', String(err?.message || err));
    } finally {
      clusterReloadRunning = false;
    }
  }, 1500);
}

async function initRuntimeStores() {
  const hotStore = await hotSegmentStore.initHotSegmentStore();
  await playlistAnalyticsStore.initPlaylistAnalyticsStore(playlistAnalyticsState, {
    persistDisk: (state) => {
      suppressClusterBroadcast = true;
      try {
        playlistAnalyticsState = state && typeof state === 'object' ? state : playlistAnalyticsState;
        saveJSON(PLAYLIST_ANALYTICS_FILE, playlistAnalyticsState);
      } finally {
        suppressClusterBroadcast = false;
      }
      broadcastStateReload('playlist_analytics').catch(() => {});
    }
  });
  playlistAnalyticsState = playlistAnalyticsStore.getMemoryMirror();
  let store = null;
  if (isRedisEnabled()) {
    store = await createSessionStore();
    if (store) {
      console.log('[runtime] session store: redis');
    } else {
      console.warn('[runtime] REDIS_URL set but session store unavailable; using MemoryStore (single-instance only)');
    }
    await initClusterStateSync(payload => scheduleClusterReload(payload));
  } else {
    console.log('[runtime] session store: memory');
  }
  sessionMiddlewareImpl = session({ ...sessionConfigBase, ...(store ? { store } : {}) });
  console.log(`[runtime] hot segment store: ${hotStore.mode}`);
  console.log(`[runtime] playlist analytics store: ${playlistAnalyticsStore.getStoreMode()}`);
  return hotStore;
}
function cleanupServices() {
  if (servicesCleanedUp) return;
  servicesCleanedUp = true;
  try { persistFirebaseUserAccountsState(); } catch {}
  try { persistFirebaseAccountSessionsState(); } catch {}
  try { koolService.destroy(); } catch {}
  try { koolLokkeService.destroy(); } catch {}
  closeRedisClient().catch(() => {});
}
process.on('exit', cleanupServices);
process.on('SIGINT', () => { cleanupServices(); process.exit(0); });
process.on('SIGTERM', () => { cleanupServices(); process.exit(0); });

